WITH payload AS (SELECT $archive_payload$[{"id":"401ae99c-ffae-5607-a6e0-f0d8c936b537","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقوق والدين -عقوق أم وتهديدها بالقتل -إيذاء أقارب -إقرار بالعقوق -تعزير بالسجن واجللد واملنع من اإلقامة مع األم يف مقر سكنها -إيداع املدعى عليه مستشفى الصحة النفسية ملعاجلته من آثار املخدرات –ندم وتوبة – أخذ تعهد بعدم التعرض .","document_number":"3452949","case_number":"3480923","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/2","year":"1434","subject":"عقوق والدين -عقوق أم وتهديدها بالقتل -إيذاء أقارب -إقرار بالعقوق -تعزير بالسجن واجللد واملنع من اإلقامة مع األم يف مقر سكنها -إيداع املدعى عليه مستشفى الصحة النفسية ملعاجلته من آثار املخدرات –ندم وتوبة – أخذ تعهد بعدم التعرض .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"        ‫رقم الصك ‪ 3452949:‬تاريخه‪1434/3/2 :‬ه رقم‬\n                                 ‫الدعوى‪3480923:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                    ‫‪ 34304052‬تاريخه‪1434/8/23 :‬هـ‬\n\n\n\n      ‫عقــوق والديــن ‪ -‬عقــوق أم وتهديدهــا بالقتــل ‪ -‬إيــذاء أقــارب ‪ -‬إقــرار‬\n      ‫بالعقــوق ‪ -‬تعزيــر بالســجن واجللــد واملنــع مــن اإلقامــة مــع األم يف مقــر‬\n      ‫ســكنها ‪ -‬إيــداع املدعــى عليــه مستشــفى الصحــة النفســية ملعاجلتــه‬\n               ‫مــن آثــار املخــدرات –نــدم وتوبــة – أخــذ تعهــد بعــدم التعــرض ‪.‬‬\n\n\n\n\n      ‫مــا اســتند إليــه القاضــي مــن املبــادئ العامــة وقواعد العدالة يف تســبيب‬\n                                                                          ‫حكمة‪.‬‬\n\n\n\n\n      ‫اتهــام املدعــى عليــه بعقــوق والدتــه وتهديدهــا بالذبــح‪ ،‬بالبحــث عــن‬\n      ‫ســوابقه عثــر لــه علــى خمــس ســوابق شــرب املســكرات وســابقة تلفــظ‬\n      ‫بألفــاظ غيــر الئقــة وســابقتني عقــوق والديــن وثــاث ســوابق حيــازة‬\n      ‫مخــدرات‪ -‬طلــب املدعــي العــام احلكــم عليــه بعقوبــة تعزيريــة‪ -‬حضــر‬\n      ‫وكيــل املدعيــة باحلــق اخلــاص (والــدة املدعــى عليــه) وادعــى مبثــل مــا‬\n      ‫ادعــى بــه املدعــي العــام وطلــب معاقبتــه بالســجن وحبســه ومنعــه مــن‬\n      ‫اإلقامــة والســكنى مــع والدتــه يف أي مســكن أو منــزل تقيــم فيــه إال‬\n      ‫ـاء لشــره ومنعــه مــن التعــرض لهــا‬\n                                         ‫برضاهــا مادامــت علــى قيــد احليــاة اتقـ ً‬\n      ‫وألبنائهــا (إخوتــه) بــأذى بعــرض دعــوى املدعــي العــام واخلــاص علــى‬\n\n‫‪289‬‬\n\f‫املدعــى عليــه صــادق عليهــا‪ ،‬وقــرر توبتــه وندمــه علــى مــا قــام بــه وفعلــه‬\n‫مــع والدتــه ‪ ،‬نظــر ًا ملصادقــة املدعــي عليــه علــى دعــوى املدعــي العــام‬\n‫واملدعيــة باحلــق اخلــاص وقــرر توبتــه وندمــه علــى مــا قــام بــه وفعلــه مــع‬\n‫والدتــه املدعيــة أصالــة باحلــق اخلــاص لــذا ثبتــت إدانــة املدعــى عليــه مبــا‬\n‫أســند إليــه شــرعاً‪ ،‬مت احلكــم علــى املدعــى عليــه بتعزيــره للحــق العــام‬\n‫واخلــاص بالســجن مــدة ســتة أشــهر وجلــده ثالثمائــة جلــده مفرقــة علــى‬\n‫أربــع فتــرات واحلكــم مبنعــه مــن اإلقامــة و املكــث يف أي مســكن أو‬\n‫منــزل تقيــم فيــه والدتــه املدعيــة أصالــة إال برضاهــا واحلكــم بإدخالــه‬\n‫إلــى مستشــفى األمــراض النفســية ملعاجلتــه مــن آثــار اســتعمال املخــدرات‬\n‫ملــدة خمســة أشــهر واحلكــم بأخــذ التعهــد القــوي عليــه لــدى اجلهــة‬\n‫املختصــة بعــدم معاودتــه لفعلتــه الشــنيعة املذكــورة بالدعــوى وعــدم‬\n‫إقامتــه أو زيارتــه ملســكن والدتــه املدعيــة أصالــة إال برضاهــا وعــدم‬\n‫التعــرض ألبنــاء املدعيــة أصالــة إخوانــه أو أخواتــه أو القــرب مــن مواقــع‬\n‫ســكنهم أو عملهــم وإن حصــل منــه خــاف ذلــك فيحــال إلــى املدعــي‬\n‫ـاء لشــره‪ ،‬بعــرض احلكــم‬       ‫العــام للمطالبــة بإخراجــه خــارج املنطقــة اتقـ ً‬\n‫علــى املدعــى العــام واملدعــي باحلــق اخلــاص وكالــة باحلــق اخلــاص قــرر‬\n‫املدعــي العــام االعتــراض بالئحــة‪ ،‬كمــا قــرر املدعــي وكالــة عــدم‬\n‫القناعــة باحلكــم ورغــب بتقــدمي الئحــة اعتراضيــة علــى احلكــم وطلــب‬\n            ‫االســتئناف فأجيــب لطلبــه كمــا قــرر املدعــى عليــه القناعــة‪.‬‬\n                   ‫بعد رفع احلكم حملكمة االستئناف متت املصادقة عليه‪.‬‬\n\n\n\n\n                                                                                        ‫‪290‬‬\n\f      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n      ‫أنــا ‪ ...‬القاضــي باحملكمــة اجلزائيــة باملدينــة املنــورة ويف هــذا اليــوم‬\n      ‫الســبت املوافــق ‪1434/2/30‬ه ـ يف متــام الســاعة التاســعة والنصف صباح ًا‬\n      ‫افتتحــت اجللســة وفيهــا حضــر املدعــي العــام ‪...‬ســعودي اجلنســية بالســجل‬\n      ‫املدنــي رقــم ‪...‬واملعمــد مــن رئيــس هيئــة التحقيــق واالدعــاء العــام برقــم‬\n      ‫‪ 17648‬ويف ‪1432/6/12‬ه ـ وادعــى علــى احلاضــر معــه ‪...‬ســعودي اجلنســية‬\n      ‫ا يف دعــواه عليــه انه يف يــوم األحد املوافق‬\n                                                   ‫بالســجل املدنــي رقــم (‪ )...‬قائـ ً‬\n      ‫‪1434/1/18‬ه ـ ويف متــام الســاعة العاشــرة مســاء ًا حضــرت إلــى مركــز‬\n      ‫شــرطة أحــد ‪ )72(...‬عامــا وادعــت علــى ابنهــا ‪ )50(...‬عامــا أنــه عــاق‬\n      ‫بهــا ودائمــا مــا يقــوم بضربهــا ويف يــوم اخلميــس فجــر اجلمعــة املاضــي‬\n      ‫حضــر إلــى املنــزل وهــو بحالــة غيــر طبيعيــة وقــام بتهديدهــا بالضــرب‬\n      ‫وهددهــا بالذبــح مذكــر ًا إياهــا بحادثــة ضربــه لهــا قبــل ثــاث ســنوات‬\n      ‫وأنــه شــخص غيــر متــزن‪ .‬وبســماع أقــوال املــرأة ‪.../‬ذكــرت أن ابنهــا‬\n      ‫‪.../‬قــام بالتلفــظ عليهــا وتهديدهــا بالذبــح وذكرهــا مبــا فعلــه بهــا قبــل‬\n      ‫نحــو ثــاث ســنوات أو أكثــر مــن قيامــه بضربهــا وحكــم فيهــا بحكــم‬\n      ‫شــرعي ‪ ,‬وأنهــا تخــاف علــى نفســها منــه وترغــب يف ســجنه كونــه‬\n      ‫يســكن معهــا يف ذات املنــزل‪ .‬وبضبــط شــهادة أخيــه ‪...‬شــهد أن املدعــى‬\n      ‫عليــه أعــاه تلفــظ علــى والدتهمــا وهددهــا بالذبــح‪ .‬وقــد صــدر بحــق‬\n      ‫املذكــور أمــر نقــل للســجن العــام برقــم (‪ )4318‬وتاريــخ ‪1434/2/4‬ه ـ‬\n      ‫ومشــفوعه أمــر متديــد توقيفــه برقــم (‪ )4314‬وتاريــخ ‪1434/2/4‬هـ اســتنادا‬\n      ‫للمــادة (‪ )108‬مــن نظــام اإلجــراءات اجلزائيــة ‪.‬وانتهــى التحقيــق إلــى اتهــام‬\n\n‫‪291‬‬\n\f‫‪.../‬بعقــوق والدتــه وتهديدهــا بالذبــح وذلــك لألدلــة والقرائــن التاليــة‪-1:‬‬\n‫شــهادة أخيه‪.../‬علــى الصفحــة(‪ )3‬مــن دفتــر التحقيــق املرفــق (‪-2.)13‬مــا‬\n‫جــاء بأقــوال والدتــه علــى الصفحــة (‪ )2‬مــن دفتــر التحقيــق املرفــق (‪.)13‬‬\n‫وبالبحــث عــن ســوابقه عثــر لــه علــى خمــس ســوابق شــرب املســكرات‬\n‫وســابقة تلفــظ بألفــاظ غيــر الئقــة وســابقتني عقــوق والديــن وثــاث‬\n‫ســوابق حيــازة مخــدرات ‪.‬وحيــث أن مــا أقــدم عليــه املدعــى عليــه فعــل‬\n‫محــرم ومعاقــب عليــه شــرع ًا أطلــب اثبــات مــا أســند إليــه واحلكــم عليــه‬\n‫بعقوبــة تعزيريــة تردعــه وتزجــر غيــره ‪ ,‬علمــا أن والدتــه ال زالــت تطالــب‬\n‫بحقهــا اخلــاص هــذه دعــواي ويف نفــس اجللســة حضــر فيهــا املدعــي‬\n‫وكالــة ‪...‬ســعودي اجلنســية بالســجل املدنــي رقــم (‪ )...‬املدعــي بالوكالــة‬\n‫عــن والدتــه املدعيــة باحلــق اخلــاص حصــة بنــت ابراهيــم عثمــان علــي‬\n‫مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل املدينــة املنــورة الثانية برقم‬\n‫‪ 24280‬يف ‪1430/4/17‬ه ـ وادعــى بوفــق مــا ادعــى بــه املدعــي العــام وطلــب‬\n‫معاقبتــه بالســجن وحبســه حتــى ال يتكــرر منــه فعــل ذلــك ومنعــه مــن‬\n‫اإلقامــة والســكنى معهــا يف أي مســكن أو منــزل تقيــم فيه إال برضاها‬\n‫مادامــت علــى قيــد احليــاة اتقــاء لشــره ومنعــه مــن التعــرض لهــا وألبنائهــا‬\n‫وهــم اخوتــه بــأذى هكــذا ادعــى‪ .‬وبســؤال املدعــى عليــه أجــاب بقولــه‬\n‫مــا ذكــره املدعــي العــام يف دعــواه صحيــح كلــه وأنــا نــادم علــى ذلــك‬\n‫هكــذا اجــاب لــذا وبعــد ســماع دعــوى املدعــي العــام واملدعــي وكالــة‬\n‫باحلــق اخلــاص وحيــث صــادق املدعــي عليــه علــى دعواهمــا وقــرر توبتــه‬\n‫وندمــه علــى مــا قــام بــه وفعلــه مــع والدتــه املدعيــة أصالــة باحلــق اخلــاص‬\n‫وبعــد اإلطــاع علــى أوراق وطيــات املعاملــة وملــا تقــدم فقــد ثبــت لــدي‬\n‫ادانــة املدعــى عليــه مبــا أســند إليــه شــرع ًا وحكمــت بتعزيــره بســجنه‬\n\n\n                                                                                        ‫‪292‬‬\n\f      ‫مــدة ســتة أشــهر وبجلــده ثالثمائــة جلــده مفرقــة علــى أربــع فتــرات بــن‬\n      ‫الفتــرة واألخــرى خمســة عشــر يومــا منهــا ثالثــة أشــهر ســجن مــن تاريــخ‬\n      ‫إيقافــه ومائــة وخمســن جلــده للحــق العــام و منهــا ثالثــة أشــهر ســجن‬\n      ‫ومائــة وخمســن جلــده للحــق اخلــاص كمــا حكمــت مبنعــه مــن اإلقامــة‬\n      ‫و املكــث يف أي مســكن أو منــزل تقيــم فيــه والدتــه املدعيــة أصالــة إال‬\n      ‫برضاهــا كمــا حكمــت بإدخالــه إلــى مستشــفى األمــراض النفســية‬\n      ‫ملعاجلتــه مــن آثــار اســتعمال املخــدرات ملــدة خمســة أشــهر كمــا حكمــت‬\n      ‫بأخــذ التعهــد القــوي عليــه لــدى اجلهــة املختصــة بعــدم معاودتــه لفعلتــه‬\n      ‫الشــنيعة املذكــورة بالدعــوى وعــدم إقامتــه أو زيارتــه ملســكن والدتــه‬\n      ‫املدعيــة أصالــة إال برضاهــا وعــدم التعــرض ألبنــاء املدعيــة أصالــة‬\n      ‫إخوانــه أو أخواتــه أو القــرب مــن مواقــع ســكنهم أو عملهــم وإن حصــل‬\n      ‫منــه خــاف ذلــك فيحــال مــع املدعــي العــام للمطالبــة بإخراجــه خــارج‬\n      ‫املنطقــة اتقــاء لشــره وبذلــك قضيــت وبعــرض احلكــم علــى املدعــى العــام‬\n      ‫واملدعــي وكالــه باحلــق اخلــاص قــرر املدعــي ا لعــام االعتــراض بالئحــة‬\n      ‫كمــا قــرر املدعــي وكالــة عــدم القناعــة باحلكــم ورغــب بتقــدمي الئحــة‬\n      ‫اعتراضيــة علــى احلكــم وطلــب االســتئناف فأجبتــه لطلبــه وأفهمتــه بــأن‬\n      ‫عليــه تقــدمي الالئحــة خــال ثالثــن يومــا تبــدأ مــن تاريــخ اســتالمه للقــرار‬\n      ‫الشــرعي املتضمــن مــا صــدر بحــق املدعــى عليــه كمــا أفهمتــه بأنــه إن‬\n      ‫تأخــر عــن تقــدمي الالئحــة خــال املــدة املذكــورة أعــاه يســقط حــق‬\n      ‫موكلتــه يف االعتــراض وترفــع املعاملــة إلــى محكمــة االســتئناف بــدون‬\n      ‫الئحــة كــون املدعــي العــام معتــرض علــى احلكــم ففهــم ذلــك وبعــرض‬\n      ‫احلكــم علــى املدعــى عليــه قــرر القناعــة باحلكــم وعلــى ذلــك جــرى‬\n      ‫التوقيــع حــرر يف ‪1434/2/30‬ه وصلــى اهلل وســلم علــى نبينــا محمــد والــه‬\n\n\n‫‪293‬‬\n\f‫وصحبــه وســلم بســجنه مــدة ســتة أشــهر وبجلــده ثالثمائــة جلــده مفرقــة‬\n‫علــى أربــع فتــرات بــن الفتــرة واألخــرى خمســة عشــر يومــا منهــا ثالثــة‬\n‫أشــهر ســجن مــن تاريــخ إيقافــه ومائــة وخمســن جلــده للحــق العــام و‬\n‫منهــا ثالثــة أشــهر ســجن ومائــة وخمســن جلــده للحــق اخلــاص احلمــد هلل‬\n‫والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ ،‬فقــد جــرى منــا نحــن‬\n‫قضــاة الدائــرة اجلزائيــة الســابعة مبحكمــة االســتئناف يف منطقــة مكة‬\n‫املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة باملدينــة املنــورة رقــم ‪ 341862560‬وتاريــخ ‪1434/8/6‬هـ ـ املرفــق‬\n‫بهــا القــرار الصــادر مــن فضيلــة الشــيخ ‪...‬القاضــي باحملكمــة اجلزائيــة‬\n‫باملدينــة املنــورة رقــم ‪ 3452949‬وتاريــخ ‪1434/3/2‬ه ـ احملكــوم فيــه مبــا‬\n‫دون بباطــن القــرار املتضمــن دعــوى املدعــى العــام ضــد‪... /‬املتهــم يف‬\n‫عقــوق وبدراســة القــرار وصــورة ضبطــه والئحتــه االعتراضيــة تقــررت‬\n‫املوافقــة علــى احلكــم بعــد اإلجــراء األخيــر‪ ،‬واهلل املوفــق ‪ .‬وصلــى اهلل‬\n                               ‫علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                   ‫‪294‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"ca29cb00-ff93-515e-9771-74b0d5d4a25f","source_page_start":289,"source_page_end":294,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"53ef85f03e96c7b3172e5a80e793c3e524ab324be54adb4e0c68a2b664b7c1a7","normalized_text_hash":"0ab8b69061d170f075a0613d05e8a54f02e74848394cfa823f002a61d2a05266","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v24-p289-3452949"},{"id":"93a0e591-f821-5bfc-a68e-37c81fdc309f","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقوق والدين -عقوق أم باإلعتداء عليها بالضرب والبصق -طلب أم بحقها اخلاص مبعاقبة أوالدها لقاء عقوقهم لها -سوابق -أمر قضائي بالكشف الطبي النفسي على املدعى عليه -إقرار بالعقوق -تعزير بالسجن واجللد والنفي عن املنطقة التي تسكن فيها األم -تعهد -إيداع أحد املدعى عليهم يف مصحة نفسية وتنفيذ احلكم عليه بعد شفائه وخروجه -تعزير للحقن العام واخلاص .","document_number":"33441188","case_number":"33210632","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف باجلوف وبرفقها قرار أصحاب الفضيلة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/10/29","year":"1434","subject":"عقوق والدين -عقوق أم باإلعتداء عليها بالضرب والبصق -طلب أم بحقها اخلاص مبعاقبة أوالدها لقاء عقوقهم لها -سوابق -أمر قضائي بالكشف الطبي النفسي على املدعى عليه -إقرار بالعقوق -تعزير بالسجن واجللد والنفي عن املنطقة التي تسكن فيها األم -تعهد -إيداع أحد املدعى عليهم يف مصحة نفسية وتنفيذ احلكم عليه بعد شفائه وخروجه -تعزير للحقن العام واخلاص .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"         ‫رقم الصك ‪ 33441188 :‬تاريخه‪1433/10/29 :‬هـ رقم‬\n                                      ‫الدعوى‪33210632:‬‬\n      ‫رقم قرار التصديق من محكمة االستئناف‪34177049 :‬‬\n                                    ‫تاريخه‪1434/4/2 :‬هـ‬\n\n\n\n          ‫عقــوق والديــن ‪ -‬عقــوق أم باإلعتــداء عليهــا بالضــرب والبصــق ‪ -‬طلــب‬\n          ‫أم بحقهــا اخلــاص مبعاقبــة أوالدهــا لقــاء عقوقهــم لهــا ‪ -‬ســوابق ‪ -‬أمــر‬\n          ‫قضائــي بالكشــف الطبــي النفســي علــى املدعــى عليــه ‪ -‬إقــرار بالعقــوق‬\n          ‫‪ -‬تعزيــر بالســجن واجللــد والنفــي عــن املنطقــة التــي تســكن فيهــا األم‬\n          ‫‪ -‬تعهــد‪ -‬إيــداع أحــد املدعــى عليهــم يف مصحــة نفســية وتنفيــذ احلكــم‬\n                    ‫عليــه بعــد شــفائه وخروجــه ‪ -‬تعزيــر للحقــن العــام واخلــاص ‪.‬‬\n\n\n\n\n          ‫‪ -‬قــال ابــن القيــم رحمــه اهلل يف إعــام املوقعــن ‪ 126_125/2‬مــا نصــه(‬\n          ‫وليــس مقصــود الشــارع مجــرد األمــن مــن املعــاودة ليــس إال‪ ..‬وإمنــا‬\n          ‫املقصــود يف الزجــر والنــكال والعقوبــة علــى اجلرميــة وأن يكــون إلــى‬\n                                         ‫كــف عدوانــه أقــرب وأن يعتبــر بــه غيــره )‪.‬‬\n          ‫‪-‬مــن أنــواع التعزيــر النفــي أو التغريــب مــن البلــد وجــاءت الشــريعة‬\n          ‫بهــذا األصــل كالــذي قتــل تســعة وتســعني نفســا وكذلــك فعــل النبــي‬\n          ‫صلــى اهلل عليــه وســلم باملخنثــن مــن الرجــال واملترجــات مــن النســاء‬\n          ‫حيــث قــال النبــي صلــى اهلل عليــه وســلم ( اخرجوهــم مــن بيوتكــم) قــال‬\n          ‫ابــن عبــاس رضــي اهلل عنــه فأخــرج النبــي صلــى اهلل عليــه وســلم فالنــا‬\n          ‫وأخــرج عمــر فالنــا) أخرجــه البخــاري ‪ 2207/5‬مــن حديــث ابــن عبــاس‬\n          ‫قــال ابــن حجــر بعــد ســياق هــذا احلديــث وغيــره مــن أحاديــث البــاب‬\n\n\n‫‪295‬‬\n\f‫( ويف هــذه األحاديــث مشــروعية إخــراج كل مــن يحصــل بــه التــأذي‬\n‫للنــاس عــن مكانــه إلــى أن يرجــع عــن ذلــك أو يتــوب ) فتــح البــاري‬\n                                                                  ‫‪.334/10‬‬\n\n\n\n\n‫انتهــى التحقيــق إلــى توجيــه االتهــام للمدعــى عليهــم (ثالثــة إخــوة)‬\n‫بعقــوق والدتهــم وذلــك باالعتــداء عليهــا بالضــرب والبصــق يف وجههــا‬\n‫‪ ،‬ومبحاولــة إحــراق املنــزل عــن طريــق ســكب مــادة (الكيروســن)‪،‬‬\n‫وذلــك بعدمــا تقدمــت والدتهــم ببــاغ للجهــات املختصــة مفــاده قيــام‬\n‫أبنائهــا بعقوقهــا وذلــك باالعتــداء عليهــا بالضــرب والبصــق يف وجههــا‪،‬‬\n‫كمــا قامــوا بتكســير أثــاث املنــزل ومحاولــة إحراقــه وذلــك بســكب‬\n‫مــادة (الكيروســن) وســكبه أيضــا علــى مالبــس بناتهــا‪ ،‬كمــا‬\n‫أفــادت بأنهــم تســببوا لهــا بعنــاء دائــم وأنهــم يضربونهــا بشــكل يومــي‪،‬‬\n‫طلــب املدعــي العــام احلكــم عليهــم بعقوبــة تعزيريــة‪ ،‬بعــرض دعــوى‬\n‫املدعــي العــام علــى املدعــى عليهــم أنكروهــا‪ ،‬ودفعــوا أن والدتهــم‬\n‫تقــوم بتهديدهــم إذا منعوهــا مــن اخلــروج مــع الســائق‪ ،‬أو عنــد تأديبهــم‬\n‫إخوانهــم‪ ،‬وأن الشــكوى عــادة لهــا عنــد أتفــه األســباب‪ ،‬حضــرت‬\n‫املدعيــة باحلــق اخلــاص (والــدة املدعــى عليهــم) وادعــت عليهــم مثــل دعــوى‬\n‫املدعــي العــام‪ ،‬وذكــرت أنهــم ســبق وأن قامــوا باالعتــداء عليهــا يف عــدة‬\n‫قضايــا وتقــوم بالتنــازل عنهــم مــن أجــل اإلصــاح إال أنهــم يعــودون إلــى‬\n‫أمورهــم املشــينة‪ ،‬وتخشــى علــى نفســها وعلــى أوالدهــا الصغــار منهــم‪،‬‬\n‫وطلبــت احلكــم بتأديبهــم ودفــع شــرهم عنهــا وعــن أبنائهــا‪ ،‬بعــرض‬\n‫دعــوى املدعيــة باحلــق اخلــاص علــى املدعــى عليهــم قــرروا خطأهــم يف‬\n\n                                                                                    ‫‪296‬‬\n\f      ‫حــق والدتهــم وطلبــوا منهــا التنــازل عنهــم وتعهــدوا بعــدم العــودة ملثــل‬\n      ‫فعلهــم كمــا قــرروا اســتعدادهم باخلــروج مــن املنــزل والذهــاب خــارج‬\n      ‫املنطقــة‪ ،‬بعــرض إجابــة املدعــى عليهــم علــى املدعيــة قــررت عــدم‬\n      ‫التنــازل ‪ ،‬جــرى االطــاع علــى ســوابق املدعــى عليــه األول‪ :‬حيــازة‬\n      ‫مخــدرات وســرقة وصــدم الدوريــة‪ ،‬وســوابق املدعــى عليــه الثانــي‪:‬‬\n      ‫ثــاث ســوابق وهــي مضاربــة جماعيــة واســتعمال مخــدرات وحيــازة‬\n      ‫واســتعمال مخــدرات‪ .‬وســوابق املدعــى عليــه الثالــث‪ :‬ســابقتني عقــوق‬\n      ‫والديــن‪ ،‬وبعرضهــا عليهــم صادقــوا عليهــا‪ ،‬متــت الكتابــة ملستشــفى‬\n      ‫الصحــة النفســية لإلفــادة عــن حالــة املدعــى عليــه الثالــث النفســية فــورد‬\n      ‫اجلــواب بتشــخيص حالتــه باضطــراب يف الشــخصية لســوء اســتخدام‬\n      ‫املــواد احملظــورة‪ ،‬وتوصــي اللجنــة نظــرا خلطورتــه املتوقعــة علــى والدتــه‬\n      ‫بإدخالــه أقــرب مستشــفى نفســي ملرجعــه وبقائــه فتــرة كافيــه حلــن‬\n      ‫انتفــاء خطورتــه جتــاه والدتــه وأنــه مســؤول جنائيــا عمــا بــدر منــه‪،‬‬\n      ‫طلــب املدعــى عليهــم التنــازل مــن والدتهــم املدعيــة باحلــق اخلــاص مــرار ًا‬\n      ‫ولــم تقبــل ذلــك‪ ،‬نظــر ًا ألن املدعــى عليهــم صادقــوا علــى دعــوى املدعــي‬\n      ‫العــام واملدعيــة باحلــق اخلــاص ومؤاخــذة للمدعــى عليهــم مبــا أقــروا بــه‬\n      ‫وألن فعلهــم يعــد كبيــرة مــن كبائــر الذنــوب وحيــث حــرم اهلل عــز‬\n      ‫وجــل عقــوق الوالديــن وجعــل أدنــى األذى وهــو التأفــف مــن العقــوق‪ ،‬وملــا‬\n      ‫ظهــر مــن نــدم املدعــى عليهــم علــى فعلهــم وألن األصــل يف التعزيــر أنــه‬\n      ‫مفــوض للقاضــي يف تقريــر العقوبــة وألن مــن أهــداف العقوبــة التعزيريــة‬\n      ‫زجــر اجلانــي وردعــه وإصالحــه وألن العقوبــات التعزيريــة اجتهاديــة‬\n      ‫غيــر محــددة بجنــس وألن مــن أنــواع التعزيــر النفــي أو التغريــب مــن‬\n      ‫البلــد وجــاءت الشــريعة بهــذا األصــل‪ ،‬وألن املدعــى عليهــم قــد تكــرر‬\n\n\n‫‪297‬‬\n\f‫منهــم الوقــوع يف مثــل هــذه القضيــة لــذا ثبتــت إدانــة املدعــى عليهــم مبــا‬\n‫نســب إليهــم بدعــوى املدعــي العــام واملدعيــة باحلــق اخلــاص ومت احلكــم‬\n‫بتعزيرهــم علــى النحــو اآلتــي‪ :‬أوال ‪ :‬يســجن كل واحــد منهــم ســنة‬\n‫كاملــة ويجلــد ثالثمائــة جلــدة مفرقــة علــى ســت دفعــات هــذا للحــق‬\n‫العــام ثانيــا ‪ :‬إبعــاد املدعــى عليهــم عــن املنطقــة ملــدة عامــن بعــد انتهــاء‬\n‫تنفيــذ احلكــم يف احلــق العــام فــإن شــوهدوا يف املنطقــة أو أحدهــم فإنــه‬\n‫يســجن الــذي خالــف هــذا احلكــم ملــدة عشــر ســنوات ويتــم إيداعــه‬\n‫الســجن فــورا وهــذا للحــق اخلــاص ثالثــا ‪ :‬إيــداع املدعــى عليــه الثالــث يف‬\n‫أحــد املصحــات النفســية ملعاجلتــه وتأهيلــه وبعــد خروجــه مــن املستشــفى‬\n‫ينفــذ عليــه احلكــم يف احلــق اخلــاص رابعــا ‪ :‬أخــذ التعهــد علــى املدعــى‬\n‫عليهــم‪ ،‬بعــرض ذلــك علــى املدعــى عليهــم واملدعيــة باحلــق اخلــاص قــرروا‬\n‫القناعــة أمــا املدعــي العــام فقــرر عــدم القناعــة وطلــب التمييــز مكتفيــا‬\n‫بالئحــة الدعــوى عــن الئحتــه االعتراضيــة‪ ،‬وبعــد رفــع احلكــم حملكمــة‬\n‫االســتئناف وبعــد مداولــة مــع ناظــر القضيــة متــت املصادقــة عليــه‪ .‬مــا‬\n‫عــدا مــا ذكــر فيمــا يخــص احلــق اخلــاص مــن أنــه عنــد مشــاهدة أحــد‬\n‫املدعــى عليهــم يف املنطقــة التــي يســكنون بهــا فيســجن عشــر ســنوات‬\n                                                               ‫فقــد تقــرر نقضــه‪.‬‬\n\n\n\n\n‫اجلزئيــة بســكاكا‬\n                ‫ّ‬      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬رئيــس احملكمــة‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا برقــم ‪ 33210632‬وتاريــخ ‪1433/03/23‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 33559178‬وتاريــخ ‪1433/03/23‬ه ـ ففــي يــوم‬\n‫األحــد املوافق‪1433/03/27‬ه ـ أفتتحــت اجللســة األولــى يف متــام الســاعة‬\n\n                                                                                         ‫‪298‬‬\n\f      ‫‪ 09 : 26‬وفيهــا قــدم املدعــي العــام الئحــة دعــوى عامــة ضــد كل مــن‬\n      ‫‪...‬ســعودي بالســجل املدنــي رقــم ‪...‬و‪ ......‬ســعودي بالســجل املدنــي رقــم ‪...‬‬\n      ‫و‪...‬ســعودي بالســجل املدنــي رقــم ‪ ...‬قائــا فيهــا بتاريــخ ‪1433/03/10‬ه ـ‬\n      ‫تقدمــت والــدة املذكوريــن ببــاغ ملركــز شــرطة ‪ ...‬مفــاده قيــام أبنائهــا‬\n      ‫املذكوريــن أعــاه بعقوقهــا وذلــك باالعتــداء عليهــا بالضــرب والبصــق‬\n      ‫يف وجههــا ‪ ،‬كمــا قامــوا بتكســير أثــاث املنــزل ومحاولــة إحراقــه‬\n      ‫وذلــك بســكب مــادة (الكيروســن) وســكبه أيضــا علــى مالبــس‬\n      ‫بناتهــا ‪ ،‬كمــا أفــادت بأنهــم تســببوا لهــا بعنــاء دائــم وأنهــم يضربونهــا‬\n      ‫بشــكل يومــي ‪ ،‬وبســؤالها عــن الــذي يضربهــا أفــادت بأنهــم جميعــا‬\n      ‫ضربوهــا أكثــر مــن مــرة ‪ ،‬كمــا ســبق أن تقدمــت والدتهــم بدعوتــن‬\n      ‫مماثلتــن ومت حفظهمــا بنــاء علــى تنازلهــا‪ .‬املســتند النظامــي لإليقــاف‪:‬‬\n      ‫اســتنادا للقــرار الــوزاري (‪ )1900‬الفقــرة (‪ .)15‬وباالنتقــال ملوقــع املنــزل‬\n      ‫اتضــح أنــه يقــع غــرب الطريــق العــام ‪ ،‬وبالدخــول للمنــزل اتضــح بــأن‬\n      ‫الصالــة الداخليــة للمنــزل بهــا آثــار ملــادة (الكيروســن) ووجــد لبــاس‬\n      ‫نســائي مبلــل مبــادة الكيروســن أيضــا ‪ ،‬كمــا أن املنــزل كان مبعثــرا‬\n      ‫بشــكل كامــل‪ .‬وبالتحقيــق مــع األول أنكــر مــا نســب إليــه مــن اتهــام‬\n      ‫‪ ،‬وأفــاد بــأن والدتــه قــد تكــون ســكبت مــادة (الكيروســن) لكــي‬\n      ‫تتهمــه مبحاولــة إحــراق املنــزل‪ .‬وبالتحقيــق مــع الثانــي أنكــر مــا نســب‬\n      ‫إليــه مــن اتهــام ‪ ،‬وأفــاد بأنــه يســكن يف شــقة مســتقلة عــن أهلــه وال‬\n      ‫عالقــة لــه بهــم وبالتحقيــق مــع الثالــث أنكــر مــا نســب إليــه مــن اتهــام‬\n      ‫‪ ،‬وأفــاد بــأن شــقيقه ‪...‬يســكن معهــم يف نفــس املنــزل يف شــقة مســتقلة‬\n      ‫‪ ،‬كمــا أفــاد بأنــه يعانــي مــن مــرض نفســي‪ .‬وانتهــى التحقيــق إلــى‬\n      ‫توجيــه االتهــام للمذكوريــن بعقــوق والدتهــم وذلــك باالعتــداء عليهــا‬\n\n\n‫‪299‬‬\n\f‫بالضــرب والبصــق يف وجههــا ‪ ،‬ومبحاولــة إحــراق املنــزل عــن طريــق‬\n‫ســكب مــادة (الكيروســن) وبعثــرة محتوياتــه‪ .‬وحيــث إن مــا أقــدم‬\n‫عليــه املذكــورون وهــم بكامــل أهليتهــم املعتبــرة شــرعا فعــل محــرم‬\n‫ومعاقــب عليــه شــرعا ويتعــن معــه إحالتهــم للمحكمــة اجلزئيــة وفقــا‬\n‫لنــص املادتــن (‪ )128.126‬مــن نظــام اإلجــراءات اجلزائيــة فإنــي أطلــب‬\n‫إثبــات مــا أســند إليهــم واحلكــم عليهــم بعقوبــة تعزيريــة بالغــة حتقــق‬\n‫زجرهــم لعظــم مــا اقترفــوه مــن خطيئــة وجنايــة وجســامة مــا قامــوا بــه‬\n‫واقعــا ولتعــدد ســوابقهم التــي تنبــئ عــن ســوء مســلكهم وملــا ســجل أيضا‬\n‫يف صحيفــة املتهــم الثالــث مــن جرميتــن متمثلتــن بعقــوق الوالدين‪( .‬علما‬\n‫بــأن احلــق اخلــاص مــا زال قائمــا) هــذه دعــواي وبعــرض دعــوى املدعــي‬\n‫العــام علــى املدعــى عليهــم أجابــوا قائلــن مــا ذكــره املدعــي العــام مــن‬\n‫أننــا قمنــا بعقــوق والدتنــا وذلــك باالعتــداء عليهــا بالضــرب والبصــق‬\n‫يف وجههــا ومبحاولــة إحــراق املنــزل عــن طريــق ســكب مــادة الــكاز‬\n‫وبعثــرة محتوياتــه فهــذا غيــر صحيــح والصحيــح أن الوالــدة عندمــا‬\n‫نقــوم مبنعهــا مــن اخلــروج مــع الســائق أو محاولــة تأديــب إخواننــا تقــوم‬\n‫بتهديدنــا وترفــض كالمنــا وأصبحــت الشــكوى عــادة لوالدتنــا عنــد‬\n‫أتفــه األســباب ونطلــب حضــور والدتنــا ومناقشــتها عــن ســبب القضيــة‬\n‫هكــذا أجابــوا وبطلــب البينــة مــن املدعــي العــام علــى دعــواه قــال بينتــي‬\n‫هــي مــا جــاء يف بــاغ والدتهــم ومــا جــاء يف محضــر االنتقــال واملعاينــة‬\n‫هكــذا أفــاد هــذا وقــد جــرى االطــاع علــى أوراق املعاملــة فوجــدت‬\n‫مــن بــن طياتهــا إفــادة املدعيــة املدونــة علــى الصحيفــة الثالثــة مــن ملــف‬\n‫االســتدالل املدونــة علــى اللفــة األولــى وكذلــك محضــر املعاينــة املــدون‬\n‫علــى الصحيفــة الثانيــة مــن نفــس دفتــر االســتدالل الســابق وباالطــاع‬\n\n\n                                                                                      ‫‪300‬‬\n\f      ‫علــى ذلــك وجدتــه كمــا ذكــر املدعــي العــام يف دعــواه وبعــرض ذلــك‬\n      ‫علــى املدعــى عليهــم قالــوا مــا جــاء يف إفــادة والدتنــا ومحضــر املعاينــة‬\n      ‫غيــر صحيــح هكــذا أفــادوا لــذا جــرى رفــع اجللســة إلحضــار املدعيــة‬\n      ‫ألخــذ مــا لديهــا وذلــك يــوم الثالثــاء القــادم املوافــق ‪1433/03/29‬ه ـ‬\n      ‫الســاعة العاشــرة‪ .‬حــرر يف ‪ 1433/03/27‬ه ـ ويف هــذا اليــوم الثالثــاء‬\n      ‫املوافــق‪ 1433/03/29‬ه ـ افتتحــت اجللســة الثانيــة يف متــام الســاعة ‪: 47‬‬\n      ‫‪ 10‬وفيهــا حضــر املدعــى عليهــم كمــا حضــر يف هــذه اجللســة املدعيــة‬\n      ‫باحلــق اخلــاص ‪ ...‬ســعودية بالســجل املدنــي رقــم ‪...‬وادعــت علــى أبنائهــا‬\n      ‫احلاضريــن قائلــة أن هــؤالء احلاضريــن هــم أبنائــي يقومــون باالعتــداء‬\n      ‫علــي بالضــرب والســب ويقومــون بتكســير أثــاث املنــزل وال ينامــون‬\n      ‫الليــل ويف هــذه املــرة حاولــوا إحــراق املنــزل بســكب الــكاز إال أننــي‬\n      ‫خرجــت أصيــح خــارج املنــزل يف الســاعة الواحــدة ليــا وأبنائــي الصغــار‬\n      ‫معــي يصيحــون ثــم هربــوا إلــى الــدور العلــوي علمــا أنــه ســبق وأن قامــوا‬\n      ‫باالعتــداء علــي يف عــدة قضايــا وأقــوم بالتنــازل عنهــم مــن أجــل اإلصــاح‬\n      ‫إال أنهــم يعــودون إلــى أمورهــم املشــينة وإنني أخشــى على نفســي وأوالدي‬\n      ‫الصغــار منهــم أطلــب احلكــم بتأديــب هــؤالء ودفــع شــرهم عنــي وعــن‬\n      ‫أبنائــي الصغــار لقــاء حقــي اخلــاص هــذه دعــواي وبعــرض دعــوى املدعيــة‬\n      ‫باحلــق اخلــاص علــى املدعــى عليهــم أجابــوا قائلــن إننــا أخطأنــا يف حــق‬\n      ‫والدتنــا ونطلــب مــن والدتنــا التنــازل عنــا ونتعهــد أمامكــم إننــا إن عدنــا‬\n      ‫ملثــل هــذه القضيــة أو غيرهــا فلــك أن حتكــم علينــا بأشــد العقوبــات‬\n      ‫كمــا إننــا ســنخرج مــن املنــزل وســوف نبحــث عــن وظائــف خــارج مدينــة‬\n      ‫ســكاكا هكــذا أجابــوا وبعــرض إجابــة املدعــى عليهــم علــى املدعيــة‬\n      ‫قالــت إن هــؤالء قــد تنازلــت عنهــم مــرارا إال إنهــم يعــودون ألفعالهــم‬\n\n\n‫‪301‬‬\n\f‫علمــا أن هــذا احلاضــر ‪ ...‬قــام بضربــي بعصــا املكنســة وقــام بســكب‬\n‫الطعــام علــى األرض وجعلــه حتــت رجليــه وهــو ســكران هكــذا أفــادت‬\n‫لــذا جــرى رفــع اجللســة إلــى يــوم األحــد القــادم ‪1433/04/04‬ه ـ الســاعة‬\n‫التاســعة لتأملهــا ودراســتها وعليــه جــرى التوقيــع وأقفلــت اجللســة يف متــام‬\n‫الســاعة احلاديــة عشــرة والربــع‪ .‬حــرر يف ‪ 1433/03/29‬ه ـ ويف هــذا اليــوم‬\n‫األحــد املوافق‪1433/04/04‬ه ـ افتتحــت اجللســة الثالثــة يف متــام الســاعة ‪01‬‬\n‫‪ 11 :‬وفيهــا حضــر املدعــى عليهــم واملدعيــة باحلــق اخلــاص هــذا وقــد جــرى‬\n‫ســؤال املدعــى عليهــم عــن ســوابقهم حيــث إن علــى املدعــى عليــه األول‬\n‫‪...‬ســابقتني هــي حيــازة مخــدرات وســرقة وصــدم الدوريــة وعلــى املدعــى‬\n‫عليــه الثانــي ‪...‬ثــاث ســوابق وهــي مضاربة جماعية واســتعمال مخدرات‬\n‫وحيــازة واســتعمال مخــدرات كذلــك وعلــى املدعــى عليــه الثالــث‬\n‫‪...‬ســابقتني عقــوق والديــن وبعــرض ذلــك علــى املدعــى عليهــم أجابــوا‬\n‫قائلــن إن الســوابق صحيحــة وقــد حكمنــا عليهــا هكــذا أفــادوا كمــا‬\n‫أفــاد املدعــى عليــه الثالــث ‪...‬إنــه يعانــي مــن مــرض نفســي ويتعالــج اآلن‬\n‫يف مستشــفى الصحــة النفســية باجلــوف هكــذا أفــاد ثــم قــام املدعــى‬\n‫عليــه األول ‪...‬بعمــل حركــة داخــل املجلــس الشــرعي برفــع صوتــه مــن‬\n‫غيــر ســبب مســتهزئا باملجلــس وباحلاضريــن ومت إخراجــه مــن املجلــس‬\n‫الشــرعي لــذا جــرى إثباتــه حتــى ال يخفــى لــذا قــررت مخاطبــة مستشــفى‬\n‫الصحــة النفســية وإفادتنــا هــل املدعــى عليــه الثالــث لديــه ملــف ومــا هــو‬\n‫مرضــه وهــل يعــي تصرفاتــه أم ال وإلــى حــن ورود التقريــر الطبــي يتــم‬\n‫مواصلــة نظــر الدعــوى لــذا جــرى رفــع اجللســة الســبت ‪1433/04/17‬ه ـ‬\n                                   ‫الســاعة التاســعة حــرر يف ‪ 1433/4/4‬ه ـ ‪.‬‬\n‫اجلزئيــة بســكاكا‬‫ّ‬      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬رئيــس احملكمــة‬\n\n\n                                                                                      ‫‪302‬‬\n\f      ‫ففــي يــوم الســبت املوافــق‪ 1433/04/17‬ه ـ افتتحــت اجللســة الرابعــة يف‬\n      ‫متــام الســاعة ‪ 10 : 51‬وفيهــا حضــر املدعــى عليهــم أمــا املدعيــة باحلــق‬\n      ‫اخلــاص فلــم حتضــر وحيــث لــم يردنــا التقريــر الطبــي اخلــاص باملدعــى‬\n      ‫عليــه الثالــث ‪...‬لــذا جــرى رفــع اجللســة إلــى يــوم الســبت ‪1433/05/01‬ه ـ‬\n      ‫الســاعة التاســعة وعليــه جــرى التوقيــع وأقفلــت اجللســة يف متــام الســاعة‬\n      ‫احلاديــة عشــرة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                          ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1433/04/17‬ه ـ‬\n      ‫اجلزائية بســكاكا‬‫ّ‬       ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬رئيــس احملكمة‬\n      ‫وبنــاء علــى املعاملــة احملالــة لنــا برقــم ‪ 33210632‬وتاريــخ ‪1433/03/23‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 33559178‬وتاريــخ ‪1433/03/23‬ه ـ ففــي يــوم‬\n      ‫االثنــن املوافق‪1433/05/17‬ه ـ افتتحــت اجللســة اخلامســة يف متــام الســاعة‬\n      ‫‪ 10 : 35‬وفيهــا حضــر املدعــى عليهــم ولــم يردنــا التقريــر الطبــي النفســي‬\n      ‫اجلنائــي الــذي يبــن مــدى مســؤولية املدعــى عليــه ‪......‬عــن تصرفاتــه لــذا‬\n      ‫جــرى رفــع اجللســة إلــى حــن ورود التقريــر املشــار إليــه وحضــور املدعيــة‬\n      ‫باحلــق اخلــاص وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                        ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/05/17‬ه ـ‬\n      ‫حــرر يف ‪1433/04/04‬ه ـ ويف هــذا اليــوم األحــد املوافق‪1433/07/27‬ه ـ‬\n      ‫افتتحــت اجللســة السادســة يف متــام الســاعة احلاديــة عشــرة والثلــث وفيهــا‬\n      ‫حضــر املدعــى عليهــم واملدعيــة باحلــق اخلــاص هــذا ولــم يردنــا التقريــر‬\n      ‫الطبــي اخلــاص باملدعــى عليــه الثالــث ويف هــذه اجللســة حاولنــا الصلــح‬\n      ‫بــن املدعيــة باحلــق اخلــاص واملدعــى عليهــم إال أن املدعيــة باحلــق اخلــاص‬\n      ‫رفضــت كمــا أفــاد املدعــى عليهــم قائلــن إننــا نكــرر مــا ذكرنــاه يف‬\n      ‫اجللســة الســابقة إننــا أخطأنــا يف حــق والدتنــا مــن عقوقهــا والتلفــظ‬\n\n\n‫‪303‬‬\n\f‫عليهــا وإثــارة املشــاكل يف املنــزل وقــد اســتفدنا مــن الســجن ونتعهــد‬\n‫أمامكــم وأمــام والدتنــا بأننــا لــن نكــرر مــا بــدر منــا وســنبحث عــن‬\n‫وظائــف لتأمــن مســتقبلنا وإن عدنــا ألي قضيــة فإننــا نتحمــل أي عقوبــة‬\n‫تصــدر بحقنــا حتــى ولــو وصلــت إلــى القتــل هكــذا قــرروا لــذا جــرى رفــع‬\n‫اجللســة ملتابعــة إصــدار تقريــر طبــي بحــق املدعــى عليــه الثالــث ورفعــت‬\n‫إلــى يــوم الســبت ‪1433/08//17‬ه ـ الســاعة التاســعة والنصــف وعليــه‬\n‫جــرى التوقيــع وأقفلــت اجللســة الســاعة احلاديــة عشــرة وأربعــن دقيقــة‪.‬‬\n                                                    ‫حــرر يف ‪1433/07/27‬ه ـ ‪.‬‬\n‫اجلزائية بســكاكا‬ ‫ّ‬      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬رئيــس احملكمة‬\n‫ففي هذا اليوم الســبت املوافق‪ 1433/08/17‬هـ افتتحت اجللســة الســابعة‬\n‫يف متــام الســاعة الثانيــة عشــرة والربــع وفيهــا حضــرت املدعيــة باحلــق‬\n‫اخلــاص ولــم يحضــر املدعــى عليهــم لــذا جــرى رفــع اجللســة إلحضــار‬\n‫املدعــى عليهــم إلــى يــوم االثنــن القــادم ‪1433/08/26‬ه ـ الســاعة التاســعة‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                            ‫وســلم ‪ .‬حــرر يف ‪1433/08/17‬ه ـ‬\n‫اجلزائية بســكاكا‬\n                ‫ّ‬        ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬رئيس احملكمة‬\n‫ففــي هــذا اليــوم االثنــن املوافق‪1433/08/26‬ه ـ افتتحــت اجللســة الثامنــة‬\n‫يف متــام الســاعة العاشــرة وفيهــا حضــرت املدعيــة باحلــق اخلــاص ولــم‬\n‫يحضــر املدعــى عليهــم لــذا جــرى رفــع اجللســة إلحضــار املدعــى عليهــم‬\n‫إلــى يــوم األربعــاء املوافــق ‪1433/09/13‬ه ـ الســاعة الثانيــة عشــرة وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حرر‬\n‫يف ‪1433/08/26‬ه ـ احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬رئيــس احملكمــة‬\n‫اجلزائيــة بســكاكا ويف هــذا اليــوم األربعــاء املوافق‪1433/09/13‬ه ـ‬     ‫ّ‬\n\n                                                                                    ‫‪304‬‬\n\f      ‫افتتحــت اجللســة التاســعة يف متــام الســاعة ‪ 12:00‬وفيهــا حضــر املدعــى‬\n      ‫عليهمــا األول والثانــي أمــا املدعــى عليــه الثالــث فلــم يحضــر حيــث‬\n      ‫مت إرســاله إلــى مستشــفى األمــل بجــدة إلصــدار تقريــر طبــي نفســي‬\n      ‫جنائــي يبــن مــدى مســؤوليته عــن تصرفاتــه كمــا أن املدعيــة باحلــق‬\n      ‫اخلــاص لــم حتضــر لــذا جــرى رفــع اجللســة لــورود التقريــر الطبــي املشــار‬\n      ‫إليــه وإحضــار املدعــى عليــه الثالــث واملدعيــة باحلــق اخلــاص وذلــك يــوم‬\n      ‫الســبت ‪1433/10/14‬ه ـ الســاعة الثامنــة والنصــف وعليــه جــرى التوقيــع‬\n      ‫وأقفلــت اجللســة يف متــام الســاعة الثانيــة عشــرة وعشــر دقائــق وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n      ‫حــرر يف ‪1433/09/13‬ه ـ ويف هــذا اليــوم األربعــاء املوافــق‪1433/10/25‬‬\n      ‫ه ـ افتتحــت اجللســة احلاديــة عشــرة يف متــام الســاعة العاشــرة والنصــف‬\n      ‫وفيهــا حضــر املدعــى عليهــم كمــا حضــرت املدعيــة باحلــق اخلــاص هــذا‬\n      ‫وقــد وردنــا خطــاب مديــر شــعبة ســجن ســكاكا رقــم ‪1/32/1580/11‬‬\n      ‫يف ‪1433/10/22‬ه ـ وبرفقــه التقريــر الطبــي النفســي اجلنائــي اخلــاص‬\n      ‫باملدعــى عليــه ‪...‬برقــم ‪ 35/625‬يف ‪1433/09/18‬ه ـ ويتضمــن بعــد‬\n      ‫املقدمــة متــت مناظرتــه مــن قبــل اللجنــة الطبيــة النفســية لدينــا بتاريــخ‬\n      ‫‪1433/09/04‬ه ـ بخصــوص مســؤوليته اجلنائيــة عمــا بــدر منــه يف قضيتــه‬\n      ‫احلاليــة وبأخــذ تاريخــه الشــخصي واملرضــي وفحــص قــواه العقليــة‬\n      ‫تبــن مــا يلــي املذكــور يراجــع مستشــفى الصحــة النفســية باجلــوف‬\n      ‫منــذ عــام ‪1425‬ه ـ وتنــوم لديهــم عــدة مــرات وشــخصت حالتــه بتاريــخ‬\n      ‫‪1431/01/13‬ه ـ (ســوء اســتخدام املــواد احملظــورة ويف عرضــه احلالــي‬\n      ‫علــى اللجنــة الطبيــة النفســية اجلنائيــة حيــث شــخصت حالتــه اضطــراب‬\n      ‫يف الشــخصية لســوء اســتخدام املــواد احملظــورة وتوصــي اللجنــة نظــرا‬\n\n\n‫‪305‬‬\n\f‫خلطورتــه املتوقعــة علــى والدتــه بإدخالــه أقــرب مستشــفى نفســي ملرجعــه‬\n‫وبقائــه فتــرة كافيــه حلــن انتفــاء خطورتــه جتــاه والدتــه كمــا أن اللجنــة‬\n‫تــرى بأنــه مســؤول جنائيــا عمــا بــدر منــه يف قضيتــه احلاليــة ) ويف هــذه‬\n‫اجللســة جــرى عــرض دعــوى املدعــي العــام علــى املدعــى عليهــم واملدعيــة‬\n‫باحلــق اخلــاص فأجابــوا قائلــن إن مــا ذكــره املدعــي العــام ووالدتنــا‬\n‫كلــه صحيــح وإننــا اســتفدنا مــن جلوســنا يف الســجن واعتبرنــا وتبنــا‬\n‫إلــى اهلل وإننــا نتعهــد بعــدم تكــرار مــا بــدر منــا وســوف نبحــث عــن‬\n‫وظائــف لتأمــن مســتقبلنا وإن عدنــا إلــى عقــوق والدتنــا أو إيــذاء‬\n‫إخواننــا أو ارتــكاب أي جرميــة فللمحكمــة أن حتكــم علينــا بالقتــل‬\n‫هكــذا أجابــوا ومبحاولــة الصلــح مــع والدتهــم قالــت إننــي ال أرغــب أن‬\n‫يســكنوا معــي يف البيــت ألننــي تنازلــت عنهــم كثيــرا ولــن أتنــازل عنهــم‬\n‫وال أســتطيع العيــش معهــم هكــذا أفــادت لــذا وبنــاء علــى مــا ســبق مــن‬\n‫الدعــوى واإلجابــة وحيــث صــادق املدعــى عليهــم علــى دعــوى املدعــي‬\n‫العــام واملدعيــة باحلــق اخلــاص ومؤاخــذة للمدعــى عليهــم مبــا أقــروا بــه‬\n‫وحيــث إن فعلهــم يعــد كبيــرة مــن كبائــر الذنــوب وحيــث حــرم اهلل‬\n‫عــز وجــل عقــوق الوالديــن وجعــل أدنــى األذى وهــو التأفيــف مــن العقــوق‬\n‫وإلــى مــا يــدل عليــه التقريــر الطبــي اجلنائــي الصــادر بحــق املدعــى عليــه‬\n‫الثالــث املشــار إليــه آنفــا وحيــث ظهــر لنــا نــدم املدعــى عليهــم علــى‬\n‫فعلهــم وحيــث إن األصــل يف التعزيــر مفــوض فيــه للقاضــي يف تقريــر‬\n‫العقوبــة وحيــث إن مــن أهــداف العقوبــة التعزيريــة زجــر اجلانــي وردعــه‬\n‫وإصالحــه يقــول ابــن القيــم رحمــه اهلل يف إعــام املوقعــن ‪126_125/2‬‬\n‫مــا نصــه( وليــس مقصــود الشــارع مجــرد األمــن مــن املعــاودة ليــس إال‪..‬‬\n‫وإمنــا املقصــود يف الزجــر والنــكال والعقوبــة علــى اجلرميــة وأن يكــون‬\n\n\n                                                                                      ‫‪306‬‬\n\f      ‫إلــى كــف عدوانــه أقــرب وأن يعتبــر بــه غيــره ) وحيــث إن العقوبــات‬\n      ‫التعزيريــة اجتهاديــة غيــر محــددة بجنــس وحيــث إن مــن أنــواع التعزيــر‬\n      ‫النفــي أو التغريــب مــن البلــد وجــاءت الشــريعة بهــذا األصــل كالــذي‬\n      ‫قتــل تســعة وتســعني نفســا وكذلــك فعــل النبــي صلــى اهلل عليــه وســلم‬\n      ‫باملخنثــن مــن الرجــال واملترجــات مــن النســاء حيــث قــال النبــي صلــى‬\n      ‫اهلل عليــه وســلم ( اخرجوهــم مــن بيوتكــم) قــال ابــن عبــاس رضــي اهلل‬\n      ‫عنــه فأخــرج النبــي صلــى اهلل عليــه وســلم فالنــا وأخــرج عمــر فالنــا)‬\n      ‫أخرجــه البخــاري ‪ 2207/5‬مــن حديــث ابــن عبــاس قــال ابــن حجــر بعــد‬\n      ‫ســياق هــذا احلديــث وغيــره مــن أحاديــث البــاب ( ويف هــذه األحاديــث‬\n      ‫مشــروعية إخــراج كل مــن يحصــل بــه التــأذي للنــاس عــن مكانــه إلــى‬\n      ‫أن يرجــع عــن ذلــك أو يتــوب ) فتــح البــاري ‪ 334/10‬وحيــث إن املدعــى‬\n      ‫عليهــم قــد تكــرر منهــم الوقــوع يف مثــل هــذه القضيــة لــذا فقــد ثبــت‬\n      ‫لــدي إدانــة املدعــى عليهــم مبــا نســب لهــم بدعــوى املدعــي العــام واملدعيــة‬\n      ‫باحلــق اخلــاص وقــررت تعزيــر املدعــى عليهــم لقــاء ذلــك وذلــك علــى النحــو‬\n      ‫اآلتــي أوال ‪ :‬يســجن كل واحــد مــن املدعــى عليهــم ســنة كاملــة مــن‬\n      ‫تاريــخ إيقــاف كل واحــد منهــم ويجلــد كل واحــد منهــم ثالثمائــة جلــدة‬\n      ‫مفرقــة علــى ســت دفعــات متســاوية بــن كل دفعــة وأخــرى عشــرة أيــام‬\n      ‫وهــذا للحــق العــام ثانيــا ‪ :‬يبعــد املدعــى عليهــم عــن منطقــة اجلــوف ملــدة‬\n      ‫عامــن مــن تاريــخ اكتســاب احلكــم الصفــة القطعيــة وذلــك بعــد انتهــاء‬\n      ‫تنفيــذ احلكــم يف احلــق العــام فــإن شــوهدوا يف املنطقــة أو أحدهــم فإنــه‬\n      ‫يســجن الــذي خالــف هــذا احلكــم ملــدة عشــر ســنوات ويتــم إيداعــه‬\n      ‫الســجن فــورا وهــذا للحــق اخلــاص ثالثــا ‪ :‬يــودع املدعــى عليــه الثالــث يف‬\n      ‫أحــد املصحــات النفســية ملعاجلتــه وتأهيلــه وبعــد خروجــه مــن املستشــفى‬\n\n\n‫‪307‬‬\n\f‫ينفــذ عليــه احلكــم يف احلــق اخلــاص رابعــا ‪ :‬يؤخــذ التعهــد علــى املدعــى‬\n‫عليهــم إن عــادوا ملثــل هــذه القضيــة فســوف تكــون عقوبتهــم شــديدة‬\n‫ورمبــا تصــل إلــى القتــل تعزيــرا وبجميــع مــا ذكــر قضيــت وبعــرض ذلــك‬\n‫علــى املدعــى عليهــم واملدعيــة باحلــق اخلــاص قــرروا القناعــة أمــا املدعــي‬\n‫العــام فقــرر عــدم القناعــة وطلــب التمييــز مكتفيــا بالئحــة الدعــوى‬\n‫عــن الئحتــه االعتراضيــة وعليــه جــرى التوقيــع وأقفلــت اجللســة يف متــام‬\n                                                         ‫الســاعة احلاديــة عشــرة ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬رئيــس احملكمة اجلزائية بســكاكا‬\n‫وف هــذا اليــوم األحــد املوافــق ‪1433/12/19‬ه ـ افتتحــت اجللســة الثالثــة‬\n‫عشــرة يف متــام الســاعة ‪ 10:30‬هــذا وقــد انتهــت املــدة النظاميــة للمدعــي‬\n‫العــام ولــم يقــدم الئحــة اعتراضيــة لــذا فــإن حقــه يف االعتــراض ســقط‬\n‫وأمــرت برفــع كامــل أوراق املعاملــة ألصحــاب الفضيلــة لتدقيــق احلكــم‬\n‫وعليــه جــرى التوقيــع وأقفلــت اجللســة يف متــام الســاعة العاشــرة وخمــس‬\n‫وثالثــون دقيقــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/12/19‬ه ـ والنصــف وبــاهلل التوفيــق‪،‬‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n‫‪1433/10/25‬ه ـ ويف هــذا اليــوم االثنــن املوافق‪1434/02/11‬ه ـ افتتحــت‬\n‫اجللســة الرابعــة عشــرة يف متــام الســاعة الثانيــة هــذا وقــد عــادت املعاملــة‬\n‫مــن محكمــة االســتئناف باجلــوف وبرفقهــا قــرار أصحــاب الفضيلــة‬\n‫رقــم ‪ 3411544‬وتاريــخ ‪1434/01/13‬ه ـ واملتضمــن بعــد املقدمــة وبدراســة‬\n‫القــرار وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة لوحــظ‬\n‫مــا يلــي‪ :‬أوال‪ :‬حكــم فضيلتــه بإبعــاد املدعــى عليهــم عــن منطقــة اجلــوف‬\n‫ملــدة عامــن مــن تاريــخ اكتســاب احلكــم القطعيــة للحــق اخلــاص مــع‬\n\n\n                                                                                       ‫‪308‬‬\n\f      ‫حكــم فضيلتــه بســجن كل واحــد منهــم ســنة اعتبــارا مــن تاريــخ‬\n      ‫إيقافــه للحــق العــام ويف هــذا لبــس وتداخــل يف األحــكام فــا بــد مــن‬\n      ‫توضيــح ذلــك ثانيــا‪ :‬حكــم فضيلتــه بإبعــاد املدعــى عليهــم عــن منطقــة‬\n      ‫اجلــوف للحــق اخلــاص وهــذا حكــم زائــد عمــا طلبتــه املدعيــة إذ طلبهــا‬\n      ‫خروجهــم مــن بيتهــا ولــو أن فضيلتــه اقتصــر يف اإلبعــاد علــى مدينــة‬\n      ‫ســكاكا لــكان أولــى نظــرا ألنهــم مــن أهــل املنطقــة وقــد يكــون‬\n      ‫خروجهــم مــن ســكاكا إلــى باقــي مــدن املنطقــة وإيــواء أقاربهــم لهــم‬\n      ‫مــن أهــل املنطقــة إصــاح لهــم وميكنهــم البحــث عــن وظائــف لهــم‬\n      ‫ملعرفــة أهلهــم وجماعتهــم بهــم ثالثــا‪ :‬حكــم فضيلتــه علــى كل واحــد‬\n      ‫مــن املدعــى عليهــم عنــد مشــاهدته يف املنطقــة خــال الســنتني بالســجن‬\n      ‫ملــدة عشــر ســنوات وإيداعــه الســجن فــورا وهــذا احلكــم يصعــب إثباتــه‬\n      ‫وقــد يعتريــه بعــض األمــور التــي قــد تــؤدي إلــى أضــرار فاألولــى عنــد‬\n      ‫مشــاهدتهم أو أحدهــم يف البلــد فيحــال للقاضــي إلجــراء مــا يلــزم حيالــه‬\n      ‫فعلــى فضيلتــه مالحظــة مــا ذكــر وإجــراء موجبــه واهلل املوفــق ‪ .‬لــذا‬\n      ‫جــرى رفــع اجللســة لدراســتها وتأملهــا إلــى يــوم الســبت ‪1434/02/16‬ه ـ‬\n      ‫الســاعة العاشــرة‪ .‬حــرر يف ‪ 1434/02/11‬ه ـ ويف هــذا اليــوم الثالثــاء‬\n      ‫املوافق‪1434/02/19‬ه ـ افتتحــت اجللســة الســابعة عشــرة يف متــام الســاعة‬\n      ‫‪ 09:15‬وبعــد تأمــل القضيــة ودراســتها لــذا قــررت اجلــواب علــى أصحــاب‬\n      ‫الفضيلــة فجوابــي علــى املالحظــة األولــى فلوجاهــة مــا ذكــره أصحــاب‬\n      ‫الفضيلــة وإلزالــة اللبــس فقــد مت إيضــاح ذلــك يف نــص احلكــم وهــي‬\n      ‫عبــارة علــى أن يكــون تنفيــذ احلكــم يف احلــق اخلــاص بعــد انتهــاء تنفيــذ‬\n      ‫احلكــم يف احلــق العــام أمــا املالحظــة الثانيــة فأقــول إن إبعــاد املدعــى‬\n      ‫عليهــم عــن منطقــة اجلــوف هــو مــن بــاب إبعادهــم عــن رفقــاء الســوء يف‬\n\n\n‫‪309‬‬\n\f‫املنطقــة وال يخفــى علــى شــريف علــم أصحــاب الفضيلــة أن اإلنســان‬\n‫إذا غيــر موطنــه وذهــب إلــى بلــد ال يوجــد لــه فيــه معرفــة فإنــه أدعــى‬\n‫إلــى اســتقامته والنــدم علــى فعلتــه ولهــذا أصــل متقــرر يف الســنة كمــا‬\n‫ذكرنــا يف حيثيــات احلكــم يف الــذي قتــل مئــة رجــل وأمــا جوابــي علــى‬\n‫املالحظــة الثالثــة فأقــول إن القــرآن والســنة جــاءت بهــذا األصــل وهــو‬\n‫الوعــد والوعيــد وجــل آيــات القــرآن الكــرمي تأتــي قبــل العقوبــة وبعدهــا‬\n‫بالوعــد والوعيــد وبعــض املتهمــن ال ينتفــع يف العقوبــة وإمنــا يكــون‬\n‫التهديــد أدعــى لــه لــذا لــم يظهــر لــي ســوى مــا حكمــت بــه وأمــرت‬\n‫برفــع أوراق املعاملــة إلــى أصحــاب الفضيلــة التخــاذ مــا يرونــه وعليــه‬\n‫جــرى التوقيــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                   ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/02/19‬ه ـ‬\n‫اجلزائية بســكاكا‬‫ّ‬       ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬رئيــس احملكمة‬\n‫ويف هــذا اليــوم األحــد املوافق‪1434/03/22‬ه ـ افتتحــت اجللســة الثامنــة‬\n‫عشــرة يف متــام الســاعة ‪ 12:15‬هــذا وقــد عــادت املعاملــة مــن محكمــة‬\n‫االســتئناف مبنطقــة اجلــوف وبرفقهــا القــرار رقــم ‪ 3461442‬وتاريــخ‬\n‫‪1434/03/14‬ه ـ واملتضمــن بعــد املقدمــة وبدراســة القــرار وصــورة‬\n‫ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة وباالطــاع علــى مــا‬\n‫أجــاب بــه فضيلــة القاضــي وأحلقــه بالقــرار وضبطــه بنــاء علــى قرارنــا‬\n‫رقــم ‪ 3411544‬وتاريــخ ‪1434/01/13‬ه ـ لوحــظ أن مــا أجــاب بــه فضيلتــه‬\n‫غيــر مقنــع وال مــاق ملــا طلــب منــه ومعلــوم أن الســوء واملنكــر انتشــر يف‬\n‫معظــم البــاد وقرنــاء الســوء موجــودون فيهــا فعلــى فضيلتــه االســتجابة‬\n‫ملــا متــت املالحظــة عليــه‪ .‬فعلــى فضيلتــه مالحظــة مــا ذكــر وإجــراء‬\n‫موجبــه انتهــى‪ .‬وجوابــا علــى مــا ذكــره أصحــاب الفضيلــة أقــول ليــس‬\n\n\n                                                                                     ‫‪310‬‬\n\f      ‫لــدي ســوى مــا حكمــت بــه وليــس عنــدي غيــره وأمــرت برفــع كامــل‬\n      ‫أوراق املعاملــة إلــى محكمــة االســتئناف التخــاذ مــا يــرون وعليــه جــرى‬\n      ‫التوقيــع وأقفلــت اجللســة يف متــام الســاعة الثانيــة عشــرة والنصــف وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                         ‫حــرر يف ‪1434/03/22‬ه ـ ‪.‬‬\n      ‫احلمد هلل وحده وبعد ‪ . . .‬فقد اطلعنـا نحن قـضـاة الدائـرة األولى لتمييز‬\n      ‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة اجلــوف علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بســكاكا الشــيخ‪/‬‬\n      ‫‪...‬برقــم ‪ 34688820‬وتاريــخ ‪1434/3/23‬ه ـ املرفــق بهــا القــرار الصــادر‬\n      ‫مــن فضيلتــه املســجل برقــم ‪ 33441188‬وتاريــخ ‪1433/10/29‬ه ـ اخلــاص‬\n      ‫بدعــوى املدعــي العــام ضــد‪ ... .../‬وشــقيقه يف قضيــة عقــوق وقــد تضمــن‬\n      ‫القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل بــه‪ .‬وبدراســة القــرار‬\n      ‫وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة وباالطــاع علــى‬\n      ‫ـاء علــى‬\n             ‫مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالقــرار وصــورة ضبطــه بنـ ً‬\n      ‫قــرارات الدائــرة رقــم ‪ 3411544‬وتاريــخ ‪1434/1/13‬ه ـ ورقــم ‪3461442‬‬\n      ‫وتاريــخ ‪1434/3/14‬ه ـ فقــد قررنــا املصادقــة علــى احلكــم بعــد اإلجــراء‬\n      ‫األخيــر فيمــا يخــص احلــق العــام واخلــاص ماعــدا مــا ذكــره فضيلتــه‬\n      ‫فيمــا يخــص احلــق اخلــاص مــن أنــه عنــد مشــاهدة أحــد املدعــى عليهــم يف‬\n      ‫منطقــة اجلــوف فيســجن ملــدة عشــر ســنوات ويــودع الســجن فــور ًا وحيــث‬\n      ‫لــم يســتجب فضيلتــه ملــا وجــه بــه وألن مــا حكــم بــه يف غيــر محلــه فقــد‬\n      ‫قررنــا نقــض احلكــم يف هــذه اجلزئيــة‪ .‬فعلــى فضيلتــه إكمــال الــازم‪.‬‬\n        ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n‫‪311‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"ca29cb00-ff93-515e-9771-74b0d5d4a25f","source_page_start":295,"source_page_end":311,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5f6cd3e0554adfcebec0bac37853296c7564536c47c0409c3b0666e683f67937","normalized_text_hash":"f9700891c21b833be2cdfaced53520171a448709c60f6c80bdba40c3d9d420eb","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v24-p295-33441188"},{"id":"1f72fe50-2afa-5196-9917-b45bde48a348","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقوق والدين-دعوى اعتداء على آخر -تهديد–شرب املسكر -إقرار املدعى عليه– حد املسكر – التعزير بالسجن واجللد.","document_number":"34178014","case_number":"34127596","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/02","year":"1434","subject":"عقوق والدين-دعوى اعتداء على آخر -تهديد–شرب املسكر -إقرار املدعى عليه– حد املسكر – التعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34178014:‬تاريخه ‪1434/4/02:‬هـ رقم‬\n                          ‫القضية ‪34127596:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34223830‬تاريخه‪1434/5/27 :‬هـ‬\n\n\n\n‫عقــوق والدين‪-‬دعــوى اعتــداء علــى آخــر‪ -‬تهديد–شــرب املســكر ‪ -‬إقــرار‬\n                  ‫املدعــى عليــه– حــد املســكر – التعزيــر بالســجن واجللــد‪.‬‬\n\n\n\n\n                           ‫قوله صلى اهلل عليه وسلم ( كل مسكر حرام)‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام علــى املدعــى عليــه بشــرب املســكر والتهجــم علــى‬\n‫والدتــه محــاو ًال االعتــداء عليهــا وبيــده ســكني حيــث مت القبــض عليــه‬\n‫مــن قبــل الدوريــات األمنيــة ‪ ,‬إثــر بــاغ مــن أخ املدعــى عليــه ‪ ,‬يتضمــن‬\n‫قيــام أخيــه املدعــى عليــه بتهديــده‪ ,‬وتهديــد أمــه ‪ ,‬وإشــهاره آللــة حــادة‬\n‫(ســكني) وطلــب املدعــي العــام إقامــة حــد املســكر بحقــه و تعزيــر‬\n‫املدعــى عليــه لقــاء التهجــم علــى والدتــه أقــر املدعــى عليــه مبــا جــاء‬\n‫بدعــوى املدعــي العــام فيمــا عــدا أنــه رفــع الســكني بوجــه أمــه طلــب‬\n‫مــن املدعــي العــام بينــة علــى رفــع املدعــى عليــه الســكني جتــاه أمــه‬\n‫فأشــار إلــى أقــوال املبلغــن يف أوراق املعاملــة احلكــم بتعزيــر املدعــى‬\n‫عليــه بالســجن واجللــد لقــاء رفعــه صوتــه علــى والدتــه واتهامــه برفــع‬\n‫الســكني بوجههــا ‪ -‬احلكــم بحــد املســكر بحــق املدعــى عليــه ‪-‬قنــع‬\n‫املدعــى عليــه باحلكــم ‪ ,‬واملدعــي العــام قــرر اعتراضــه علــى احلكــم‬\n                ‫بــدون الئحــة ‪ -‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n                                                                                    ‫‪318‬‬\n\f      ‫اجلزائية‬\n        ‫ّ‬      ‫احلمد هلل وحده وبعد فلدي أنا القاضي ‪ ..............‬يف احملكمة‬\n      ‫باالحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة يف محافظــة االحســاء برقــم ‪ ...........‬بتاريــخ ‪ 1434/03/17‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم وتاريــخ ‪ 1434/03/17‬ه ـ ففــي يــوم الثالثــاء‬\n      ‫املوافــق‪ 1434/04/02‬ه ـ افتتحــت اجللســة الســاعة ‪ 09 : 00‬وفيهــا حضــر‬\n      ‫املدعــي العــام املعمــد بالترافــع أمــام هــذه احملكمــة مبوجــب خطــاب‬\n      ‫ســعادة رئيــس دائــرة التحقيــق واالدعــاء العــام مبحافظــة االحســاء‬\n      ‫ذي الرقــم ‪ 13415‬والتاريــخ ‪ 1433/12/01‬ه ـ وادعــى ضــد احلاضــر معــه‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ............‬إنــه بتاريــخ‬\n      ‫‪1434/1/2‬ه ـ مت القبــض علــى املدعــى عليــه مــن قبــل رجــال الدوريــات‬\n      ‫األمنيــة مبحافظــة األحســاء إثــر ورود بــاغ مــن املدعــو ‪ .......... /‬مفــاده‬\n      ‫قيــام أخيــه املدعــى عليــه بتهديــده وتهديــد والدتــه وإشــهاره آللــة حــادة‬\n      ‫( ســكني ) ‪ ،‬وباالنتقــال للموقــع لوحــظ بــأن املدعــى عليــه يف حالــة‬\n      ‫غيــر طبيعيــة (ســكر)‪ ،‬وباستشــمامه اتضــح انبعــاث رائحــة املســكر‬\n      ‫مــن جوفــه وقــد أثبــت تقريــر الســموم الشــرعية رقــم () لعــام ه ـ الصــادر‬\n      ‫مــن املركــز اإلقليمــي ملراقبــة الســموم إيجابيــة العينــة املرســلة لســوائل‬\n      ‫املدعــى عليــه ملركبــات احلشــيش املخــدر ( فرزت أوراق مســتقلة بشــأنها‬\n                                              ‫ملعاجلتهــا مــن قبــل اجلهــة املختصــة ) ‪.‬‬\n      ‫وبضبــط إفــادة املبلــغ املدعــو‪ ....../‬أفــاد بقيــام أخيــه املدعــى عليــه‬\n      ‫باحلضــور للمنــزل وهــو يف حالــة ســكر وقــام بالتلفــظ عليــه وعلــى‬\n      ‫والدتــه وهــو يحمــل ســكين ًا بيــده‪ .‬وبضبــط إفــادة والــدة املدعــى عليــه‬\n\n‫‪319‬‬\n\f‫أفــادت بقيــام املدعــى عليــه بالدخــول لغرفتهــا بينمــا هــي نائمــة والتهجــم‬\n‫عليهــا وبيــده ســكين ًا محــاو ًال ضربهــا قبــل أن يتدخــل شــقيقه ويأخــذ‬\n                                                             ‫الســكني مــن يــده ‪.‬‬\n‫وباســتجواب املدعــى عليــه أقــر بصحــة واقعــة القبــض عليــه وشــربه‬\n‫للمســكر بعــد أن قــام بشــرائه مــن شــخص هنــدي مببلــغ (‪ )30‬ثالثــون‬\n‫ريــا ًال ‪ ،‬ورفــع صوتــه علــى والدتــه ‪ .‬وقــد أســفر التحقيــق عــن توجيــه‬\n‫االتهــام لــه بشــرب املســكر ‪ ،‬والتهجــم علــى والدتــه محــاو ًال االعتــداء‬\n                   ‫عليهــا وبيــده ســكني؛ وذلــك لألدلــة والقرائــن التاليــة ‪:‬‬\n‫‪ .1‬إقــراره املــدون علــى الصفحــة رقــم ( ‪ ) 2‬مــن دفتــر التحقيــق لفــة رقــم‬\n                                                                               ‫(‪.)1‬‬\n‫‪ .2‬محضــر االستشــمام املــدون علــى الصفحــة رقــم ( ‪ ) 6‬مــن دفتــر‬\n                                                      ‫التحقيــق لفــة رقــم ( ‪. ) 2‬‬\n                                   ‫‪ .3‬محضر القبض املرفق على لفة رقم ( ‪. ) 3‬‬\n‫‪ .4‬أقــوال املبلغــن املدونــة علــى الصفحــة رقــم ( ‪ ) 13 ، 9‬مــن دفتــر‬\n                                                      ‫التحقيــق لفــة رقــم ( ‪. ) 2‬‬\n‫وبالبحــث عمــا إذا كان لــه ســوابق مت العثــور علــى ســابقة واحــدة‬\n‫مســجلة عليــه وهــي ترويــج املخــدرات والهــروب مــن الســلطة‪ .‬وحيــث إن‬\n‫مــا أق ــدم عليــه املدعــى علي ــه وه ــو بكامــل أهليتــه املعتبــرة ش ــرع ًا فعــل‬\n‫مح ــرم ومع ــاقب علي ــه ش ــرعاً؛ أطلــب إثبــات مــا أســند إليــه ‪ ،‬واحلكــم‬\n                                                                     ‫عليــه باآلتــي ‪:‬‬\n                                           ‫‪ .1‬بعقوبة حد املسكر لقاء شربه له ‪.‬‬\n            ‫‪ .2‬بعقوبة تعزيرية لقاء التهجم على والدته ورفع صوته عليها ‪.‬‬\n‫( علم ـ ًا بــأن احلــق اخلــاص انتهــى بالتنــازل ) هــذه دعــواي وبســؤال‬\n\n\n                                                                                          ‫‪320‬‬\n\f      ‫املدعــى عليــه أجــاب قائــا مــا ذكــره املدعــي العــام مــن أنــه بتاريــخ‬\n      ‫‪1434/01/02‬ه ـ مت القبــض علــي وأننــي كنــت يف حالــة ســكر وأننــي‬\n      ‫رفعــت صوتــي علــى والدتــي أطلــب منهــا االتصــال علــى أختهــا مــن أجــل‬\n      ‫أن يســلم لــي أبــن خالتــي جواالتــي فهــذا كلــه صحيــح وكذلــك مــا‬\n      ‫ذكــره املدعــي العــام مــن وجــود ســابقة ترويــج علــي فصحيــح أيض ـ ًا‬\n      ‫وأمــا مــا ذكــره املدعــي العــام مــن أننــي رفعــت الســكني علــى والدتــي‬\n      ‫فهــذا غيــر صحيــح هكــذا أجــاب وبســؤال املدعــي العــام هــل لديــه بينــة‬\n      ‫ا بينتــي‬  ‫علــى أن املدعــى عليــه رفــع الســكني علــى والدتــه أجــاب قائ ـ ً‬\n      ‫مــا ذكرتــه يف أوراق املعاملــة مــن أقــوال املدعــى عليــه واملبلغــن هكــذا‬\n      ‫أجــاب ثــم جــرى االطــاع علــى املعاملــة فوجــد فيهــا علــى صفحــة رقــم ‪2‬‬\n                ‫مــن دفتــر التحقيــق لفــة رقــم (‪ )1‬أقــوال املدعــى عليــه املطابقــة‬\n      ‫ملــا ذكــره يف مجلــس احلكــم كمــا جــرى االطــاع علــى أقــوال املبلغــن‬\n      ‫وهمــا والــدة املدعــى عليــه وأخــوه علــى صفحة (‪ )13-9‬مــن دفتر التحقيق‬\n      ‫لفــة رقــم ‪ 2‬والتــي تتضمــن قيــام املدعــى عليــه برفــع الســكني قبــل أن‬\n      ‫يأخذهــا أخــوه منــه فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث إن‬\n      ‫املدعــى عليــه أقــر بشــربه للمســكر وبرفــع صوتــه علــى والدتــه وأنكــر‬\n      ‫رفعــه للســكني وحيــث إن املدعــي العــام أحضــر بينــة وهــي أقــوال‬\n      ‫املبلغــن التــي ال تقبــل بينــة يف مواجهتــه ألنهــم كاألخصــام لــه إال انــه‬\n      ‫ال يعفيــه مــن العقوبــة للتهمــة كــون املبلــغ والدتــه وهــذا يســتبعد منهــا‬\n      ‫نظــر َا لرحمــة الوالــدة بولدهــا ولقــول النبــي صلــى اهلل عليــه وســلم كل‬\n      ‫مســكر حــرام لذلــك كلــه فقــد ثبــت لــدي إدانــة املدعــى عليــه بشــرب‬\n      ‫املســكر ورفــع الصــوت علــى والدتــه ولــم يثبــت لــدي رفعــه للســكني‬\n                                                           ‫وحكمــت عليــه مبــا يلــي‪:‬‬\n\n\n‫‪321‬‬\n\f              ‫اوالً‪ :‬جلد املدعي عليه ثمانني جلدة دفعة واحدة حد املسكر‬\n‫ثاني ـاً‪ :‬ســجن املدعــي عليــه لقــاء رفعــه صوتــه علــى والدتــه وتهمــة‬\n‫رفعــه للســكني مــدة ســتة أشــهر يحتســب منهــا مــدة بقائــه بالســجن‬\n‫بخصــوص هــذه القضيــة وجلــده مائــة وخمســن جلــد ًة تعزيــر ًا مفرقــة‬\n‫علــى ثــاث دفعــات كل دفعــة خمســن جلــدة بــن الدفعــة واألخــرى‬\n‫مــدة أســبوعني وبعــرض احلكــم علــى املدعــي العــام واملدعــى عليــه قــرر‬\n‫املدعــي العــام اعتراضــه علــى احلكــم وطلــب رفــع املعاملــة إلــى محكمــة‬\n‫االســتئناف بــدون الئحــة فأجبتــه لطلبــه وأمــا املدعــى عليــه قــرر قناعتــه‬\n‫بــه وبــه ختمــت اجللســة يف متــام الســاعة التاســعة والنصــف صباحـ ًا وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                     ‫حــرر يف ‪ 1434/04/02‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة األحســاء برقــم وتاريــخ‬\n‫‪1434/4/15‬ه ـ املقيــدة لــدى احملكمة برقــم وتاريخ ‪1434/4/21‬هـ املرفق‬\n‫بهــا القــرار الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ املســجل‬\n‫برقــم وتاريــخ ‪1434/ 2/2‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪ /‬يف‬\n‫قضيــة مســكر واعتــداء وتلفــظ وقــد تضمــن القــرار حكــم فضيلتــه‬\n‫مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق‬\n‫املعاملــة قررنــا املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى‬\n                ‫نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف ‪1434/5/ 22‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                         ‫‪322‬‬\n\f323\n\f324\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"ca29cb00-ff93-515e-9771-74b0d5d4a25f","source_page_start":318,"source_page_end":324,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"fd6c9d4ec8b275875289d141e02543780c965dbfdcf3e580ee6bbbf8bd8de826","normalized_text_hash":"977c7e7da0c890d6e3bc43e6ae8adaf543b15a738796c72fe19ab2d108bf31b8","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v24-p318-34178014"},{"id":"b17b11d1-c120-5a38-b6aa-e3b7d3b1ec51","document_type":"judgment","category":"judicial","subcategory":"general","title":"ميسر -شراء أوراق اليانصيب -إقرار -ثبوت -أدلة الشريعة يف حترمي القمار -التعزير -السجن -النصح -التوبيخ .","document_number":"34190287","case_number":"33451003","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/26","year":"1434","subject":"ميسر -شراء أوراق اليانصيب -إقرار -ثبوت -أدلة الشريعة يف حترمي القمار -التعزير -السجن -النصح -التوبيخ .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34190287 :‬تاريخه‪1434/4/26 :‬هـ‬\n                         ‫رقم الدعوى‪33451003 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34241773‬تاريخه‪1434/6/14 :‬هـ‬\n\n\n      ‫ميســر ‪ -‬شــراء أوراق اليانصيــب ‪ -‬إقــرار ‪ -‬ثبــوت ‪ -‬أدلــة الشــريعة يف‬\n                ‫حتــرمي القمــار ‪ -‬التعزيــر‪ -‬الســجن ‪ -‬النصــح ‪ -‬التوبيــخ ‪.‬‬\n\n\n\n\n      ‫‪ .1‬قــول اهلل تعالــى( يــا أيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر واألنصاب‬\n      ‫واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون ) ولقوله‬\n      ‫تعالــى( يســألونك عــن اخلمــر وامليســر قــل فيهمــا إثــم كبيــر ومنافــع‬\n                                          ‫للنــاس وإثمهمــا أكبــر مــن نفعهمــا )‪.‬‬\n                ‫‪ .2‬ملا جاء عن ابن عباس رضي اهلل عنه ( امليسر هو القمار )‪.‬‬\n\n\n\n\n      ‫اتهــام املدعــي العــام للمدعــى عليهــم بقيامهــم باللعــب بالقمــار ‪ ،‬يطلــب‬\n      ‫إثبــات مــا أســند إليهــم و احلكــم عليهم بعقوبــة تعزيرية‪ ،‬حيث إنه قبض‬\n      ‫علــى املذكوريــن مــن قبــل مركــز هيئــة ‪ .......‬بعــد توفــر معلومــات لــدى‬\n      ‫املركــز عــن قيــام شــخص من اجلنســية ‪ ....‬بلعب وجمــع أوراق القمار فتم‬\n      ‫انتقــال الفرقــة للموقــع للتأكــد مــن صحــة املعلومــات فشــاهدت الفرقــة‬\n      ‫املذكوريــن ومعهمــا املدعــو‪(.../‬مت حفــظ األوراق بحقــه ملخالفتــه لنظــام‬\n      ‫اإلقامــة) وهــم يقومــون بجمــع املبلــغ واألوراق اخلاصــة بلعــب القمــار فتــم‬\n      ‫القبــض عليهــم متلبســن وضبــط بحوزتهــم مبلــغ وقدره(‪)970‬ريــال ‪،‬‬\n\n‫‪325‬‬\n\f‫وبســماع أقــوال األول أقــر مبمارســة لعبــة القمــار حيــث إنــه يقــوم بشــراء‬\n‫أوراق عبــارة عــن مبالــغ ماليــة للعــب فيهــا ‪ ،‬وقــد أســفر التحقيــق عــن‬\n‫توجيــه االتهــام للمذكوريــن بلعــب القمــار وبعــرض دعــوى املدعــى العــام‬\n‫علــى املدعــى عليــه‪ ،‬أنكــر مــا جــاء يف الدعــوى وصــادق علــى شــراء‬\n‫اليانصيــب ‪ ،‬فبنــاء علــى مــا تقــدم وألن مــا أقــدم عليــه املدعــى عليــه‬\n‫األول نــوع مــن أنــوع امليســر الدائــر بــن ال ُغ ْنــم وال ُغـ ْـرم احملــرم فحكمــت‬\n‫احملكمــة عليــه باالكتفــاء مبــدة إيقافــه بالســجن علــى هــذه القضيــة‪.‬‬\n‫وأخــذ التعهــد عليــه بعــدم العــودة ملــا صــدر منــه‪ .‬وجــرى تذكيــره بــاهلل‬\n‫وعــدم التســاهل يف احملرمــات‪ .‬وصــرف النظــر عــن دعــوى املدعــي العــام‬\n‫مبصــادرة املبلــغ اخلــاص بــه وإلــزام املدعــي العــام بإعادتــه ‪ .‬وقــرر املدعــي‬\n‫العــام االعتــراض وطلــب االســتئناف بــدون الئحــة وقــرر املدعــى عليــه‬\n                       ‫وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬          ‫القناعــة‪ُ .‬‬\n\n\n\n‫احلمد هلل وحده وبعد فلدي أنا ‪ .....‬القاضي املكلف بالعمل يف املكتب‬\n‫القضائــي الســادس والثالثــون بنــاء علــى كتــاب رئيــس احملكمــة اجلزائيــة‬\n‫بالريــاض رقم‪34/476593‬يف‪1434/2/25‬ه ـ وبناء على املعاملة احملالة‬\n‫لنــا مــن فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض برقــم ‪33451003‬‬\n‫وتاريــخ ‪1433/07/07‬ه ـ املقيــدة باحملكمــة برقــم ‪331275256‬‬\n‫وتاريــخ ‪1433/07/07‬ه ـ ففــي يــوم الثالثــاء املوافــق‪ 1434/04/16‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪11 : 00‬وفيهــا حضــر املدعــي العــام ‪ ....‬وحضــر‬\n‫حلضــوره‪ .... /1:‬ســنة باكســتاني اجلنســية مبوجــب رخصــة اإلقامــة‬\n‫رقــم (‪ )....‬غيــر محصــن متعلــم موقــوف بتاريــخ ‪1433/6/10‬ه ـ ومت‬\n\n                                                                                           ‫‪326‬‬\n\f      ‫اإلفــراج عنــه مبوجــب أمــر اإلفــراج رقــم (ه ـ ر‪ )64744/3/1‬وتاريــخ‬\n      ‫‪1433/6/11‬ه ـ اســتنادا للمــادة (‪ )120‬مــن نظــام اإلجــراءات اجلزائيــة‬\n      ‫‪28 ..../2‬ســنة بنجالديشــي اجلنســية مبوجــب رخصــة اإلقامــة رقــم (‪)....‬‬\n      ‫غيــر محصــن متعلــم موقــوف بتاريــخ ‪1433/6/10‬ه ـ ومت اإلفــراج عنــه‬\n      ‫مبوجــب أمــر اإلفــراج رقــم (ه ـ ر‪ )64744/3/1‬وتاريخ‪1433/6/11‬ه ـ‬\n      ‫اســتنادا للمــادة (‪ )120‬مــن نظــام اإلجــراءات اجلزائيــة وادعــى املدعــي‬\n      ‫العــام علــى املدعــى عليــه قائــا‪ :‬أنــه بتاريــخ ‪1433/6/10‬ه ـ قبــض‬\n      ‫علــى املذكوريــن مــن قبــل مركــز هيئــة ‪ ......‬بعــد توفــر معلومــات لــدى‬\n      ‫املركــز عــن قيــام شــخص مــن اجلنســية الباكســتانية بلعــب وجمــع‬\n      ‫أوراق القمــار فتــم انتقــال الفرقــة للموقــع للتأكــد مــن صحــة املعلومــات‬\n      ‫فشــاهدت الفرقــة املذكــوران ومعهمــا املدعــو‪( ..../‬مت حفــظ األوراق‬\n      ‫بحقــه ملخالفتــه لنظــام اإلقامــة) وهــم يقومــون بجمــع املبلــغ واألوراق‬\n      ‫اخلاصــة بلعــب القمــار فتــم القبــض عليهــم متلبســن وضبــط بحوزتهــم‬\n      ‫مبلــغ وقــدره (‪ )970‬ريــال بســماع أقــوال األول‪/‬أقــر مبمارســة لعبــة‬\n      ‫القمــار حيــث أنــه يقــوم بشــراء أوراق عبــارة عــن مبالــغ ماليــة للعــب فيهــا‬\n      ‫وقــد أســفر التحقيــق عــن توجيــه االتهــام للمذكوريــن بلعــب القمــار‬\n      ‫وذلــك لألدلــة والقرائــن التالية‪/1‬مــا جــاء يف أقــوال األول املدونــة علــى‬\n      ‫الصفحــة رقــم (‪ )10-9‬مــن دفتــر التحقيــق رقم (‪/2)1‬مــا جاء يف محضر‬\n      ‫القبــض املرفــق لفــة رقــم (‪ )4‬وببحــث ســوابقهم لــم يتبــن لهــم ســوابق‬\n      ‫مســجله حتــى تاريخــه وحيــث أن مــا أقــدم عليــه املذكــورون فعــل محــرم‬\n      ‫ومعاقــب عليــه شــرع ًا أطلــب إثبــات مــا أســند إليهــم و احلكــم عليهــم‬\n      ‫بعقوبــة تعزيريــة هــذه دعــواي وبــاهلل التوفيــق وبعــرض دعــوى املدعــي‬\n      ‫العــام علــى املدعــى عليــه األول أجــاب قائــا مــا ذكــره املدعــي العــام يف‬\n\n\n‫‪327‬‬\n\f‫دعــواه غيــر دقيــق والصحيــح أننــي قمــت بشــراء أوراق يانصيــب بقيمــة‬\n‫‪460‬ريــال أربعمائــة وســتون ريــاال عــدد ‪36‬ورقــة ومــن باعهــا قــال لــي بأنــه‬\n‫ســوف يتــم كشــف أرقــام هــذه األوراق يف تايلنــد فــإذا تطابــق الرقــم‬\n‫مــع األصــل يف تايلنــد فســتربح مبلغــا أكبــر هكــذا أجــاب وبالرجــوع‬\n‫ألوراق املعاملــة ومــا جــاء يف محضــر القبــض املرفــق لفــة رقم(‪)4‬ومــا جــاء‬\n‫يف محضــر االســتدالل صفحــة رقــم(‪ )10-9‬ودفتــر التحقيــق رقــم(‪)1‬‬\n‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وإلقــرار املدعــى عليــه األول‬\n‫علــى شــراء أوراق يانصيــب بقيمــة ‪460‬ريــال أربعمائــة وســتون ريــاال وألن‬\n‫مــا أقــدم عليــه املدعــى عليــه األول نــوع مــن أنــوع امليســر الدائــر بــن‬\n‫الغنــم والغــرم احملــرم شــرعا ولقولــه تعالــى( يــا أيهــا الذيــن آمنــوا إمنــا‬\n‫اخلمــر وامليســر واألنصــاب واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه‬\n‫لعلكــم تفلحــون ) ولقولــه تعالــى( يســألونك عــن اخلمــر وامليســر قــل‬\n‫فيهمــا إثــم كبيــر ومنافــع للنــاس وإثمهمــا أكبــر مــن نفعهمــا )وملــا جــاء‬\n‫عــن ابــن عبــاس رضــي اهلل عنــه امليســر هــو القمــار وألنــه صــورة مــن‬\n‫أكل أمــوال النــاس بالباطــل وألن املدعــى عليــه قــام بالشــراء ولــم يقــم‬\n‫بعمليــة البيــع واالحتيــال وأخــذ أمــوال النــاس بالباطــل ومحتــال عليــه‬\n‫لذلــك كلــه فقــد قــررت مــا يلــي أوال‪ :‬ثبــت لــدي قيــام املدعــى عليــه‬\n‫األول باملشــاركة يف شــراء ورق امليســر احملــرم شــرعا ثانيــا‪ :‬حكمــت‬\n‫علــى املدعــى عليــه األول باالكتفــاء مبــدة إيقافــه بالســجن علــى هــذه‬\n‫القضيــة وأخــذ التعهــد عليــه بعــدم العــودة ملــا صــدر منــه كمــا جــرى‬\n‫تذكيــره بــاهلل وعــدم التســاهل يف احملرمــات ثالثــا‪ :‬صرفــت النظــر‬\n‫عــن دعــوى املدعــي العــام مبصــادرة املبلــغ اخلــاص بــه وقــدره ‪460‬ريــال‬\n‫أربعمائــة وســتون ريــاال وألزمــت املدعــي العــام بإعادتــه وبذلــك كلــه‬\n\n\n                                                                                        ‫‪328‬‬\n\f      ‫حكمــت وبعــرض ذلــك علــى املدعــى عليــه قــرر قناعتــه بــه كمــا قــرر‬\n      ‫املدعــي العــام عــدم القناعــة مكتفيــا بالئحــة الدعــوى وصلــى اهلل علــى‬\n           ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/04/16‬ه ـ‬\n      ‫احلمــد هلل وحــده أطلــع قضــاة الدائــرة اجلزائيــة األولــى علــى املعاملــة‬\n      ‫الــواردة مــن احملكمــة اجلزائيــة بالريــاض برقــم ‪ 34935925‬وتاريــخ‬\n      ‫‪1434/4/29‬ه ـ واملرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي ‪/‬‬\n      ‫‪ ...‬برقــم ‪ 34190287‬وتاريــخ ‪1434/4/16‬ه ـ واخلــاص بدعــوى املدعــي‬\n      ‫العــام ضد‪»..../‬باكســتاني اجلنســية» ورفيقــه وموضوعهــا قضيــة لعــب‬\n      ‫قمــار وانتهــاء الدراســة والتدقيــق باملصادقــة علــى احلكــم لعــدم موجــب‬\n                        ‫املالحظــة وصلــى اهلل علــى نبينــا محمــد واهلل املوفــق ‪.‬‬\n\n\n\n\n‫‪329‬‬\n\f330\n\f331\n\f332\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"ca29cb00-ff93-515e-9771-74b0d5d4a25f","source_page_start":325,"source_page_end":332,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"8036e2e681f4ee6407e228d315d4df0b5dfa11ffa3dc115512f39ca0057be9bb","normalized_text_hash":"0f18aa7e111732a82f74b0898375be97eef0925843855a52b070b80b56e9bc0f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v24-p325-34190287"},{"id":"155b57d5-dac7-5c40-9cd2-68dab8b2cb60","document_type":"judgment","category":"judicial","subcategory":"general","title":"تسول -إقامة دعوى عامة على رب أسرة لتركه أوالده ميتهنون التسول -أسباب تخفيف العقوبة -االكتفاء بأخذ التعهد .","document_number":"34176550","case_number":"40304","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/1","year":"1434","subject":"تسول -إقامة دعوى عامة على رب أسرة لتركه أوالده ميتهنون التسول -أسباب تخفيف العقوبة -االكتفاء بأخذ التعهد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34176550 :‬تاريخه‪1434/4/1 :‬هـ‬\n                            ‫رقم الدعوى‪40304 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34243027‬تاريخه‪1434/6/17 :‬هـ‬\n\n\n      ‫تســول ‪ -‬إقامــة دعــوى عامــة علــى رب أســرة لتركــه أوالده ميتهنــون‬\n        ‫التســول ‪ -‬أســباب تخفيــف العقوبــة ‪ -‬االكتفــاء بأخــذ التعهــد ‪.‬‬\n\n\n\n\n      ‫مــا اســتند إليــه القاضــي مــن املبــادئ العامــة وقواعد العدالة يف تســبيب‬\n                                                                          ‫حكمه‪.‬‬\n\n\n\n\n      ‫جــرى توجيــه االتهــام مــن املدعــي العــام للمدعى عليه بترك أفراد أســرته‬\n      ‫بــا إعالــة وبتكــرار التســول والتهــاون يف إنهــاء إجراءاتهــم النظاميــة‬\n      ‫لالســتفادة مــن اجلمعيــات اخليريــة وطلــب إيقــاع العقوبــة التعزيريــة عليــه‬\n      ‫‪ -‬حيــث قبــض علــى إبنــة املدعــى عليــه لقيامهــا بتكــرار التســول للمــرة‬\n      ‫الثالثــة والعشــرين ويرافقهــا بعــض أخوتهــا وقــد جــرى ســؤاله عــن عــدم‬\n      ‫قيامــه باســتخراج أوراق ثبوتيــة لالســتفادة مــن اجلمعيــات اخليريــة فلــم‬\n      ‫يجــب ‪ ،‬كمــا أفــاد بأنــه لــم يبحــث عــن عمــل مناســب مكتفيــا مبــا‬\n      ‫يجلــب لــه أوالده مــن التســول ‪ -‬أقــر املدعــى عليــه مبــا ذكــره املدعــي‬\n      ‫العــام وأنــه ميتهــن وأســرته التســول ‪ ،‬ودفــع بــأن الباعــث لــه هــو الفقــر‬\n      ‫واحلاجــة لكونــه متــزوج مــن زوجتــن ويعــول ثمانيــة عشــر فــردا ‪ ،‬وأنــه‬\n      ‫حصــل وأربعــة مــن أوالده علــى عمــل وأنــه متعهــد بتركــه التســول ومبنــع‬\n\n‫‪333‬‬\n\f‫أوالده مــن أن ميارســوه ‪ -‬بنــاء علــى الدعــوى واإلجابــة وملــا ظهــر مــن أن‬\n‫الدافــع لتســول املدعــى عليــه العــوز ‪ ،‬وألنــه حصــل مؤخــرا علــى عمــل‬\n‫وألنــه أظهــر ندمــه علــى مــا فعــل ‪ ،‬لذلــك كلــه فقــد قــررت احملكمــة‬\n‫احلكــم بأخــذ التعهــد علــى املدعــى عليــه بعــدم العــودة ملــا بــدر منــه وأن‬\n‫يســتمر يف البحــث عــن املــال بطــرق شــريفة ‪ -‬قنــع املدعــى عليــه باحلكــم‬\n‫بينمــا اعتــرض املدعــي العــام وطلــب رفــع القضيــة حملكمــة االســتئناف‬\n                ‫بــدون الئحــة ‪ -‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...........‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم ‪ .......‬وتاريــخ ……‪ ..‬املقيــدة باحملكمــة برقــم‬\n‫……… وتاريــخ ‪ ...........‬ففــي يــوم االثنــن املوافــق ‪1434/04/01‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 01 : 00‬وفيهــا قــدم املدعــي العــام‪........... /‬‬\n‫دعــواه علــى‪)43(........... /‬عام ـ ًا ســعودي اجلنســية مبوجــب الســجل‬\n‫ا إنــه بتاريــخ‪ ........‬قبــض علــى ابنــة‬\n                                          ‫املدنــي رقــم (‪ )...........‬مفــرج عنــه قائـ ً‬\n‫املذكــور ‪...........‬لقيامهــا بتكــرار التســول للمــرة الثالثــة والعشــرين‬\n‫ترافقها أخواتها‪........... /‬و‪ ...........‬و‪ ...........‬لغرض التســول وباســتجواب‬\n‫املذكــور‪ /‬أفــاد أن مــا يقــوم بــه أبنــاؤه مــن ممارســة التســول لغــرض‬\n‫ســد حاجتهــم ومبناقشــته عــن عــدم قيامــه بالعمــل علــى اســتخراج أوراق‬\n‫ثبوتيــة لالســتفادة مــن اجلمعيــات اخليريــة لــم يبــد جوابـ ًا وكذلــك حينمــا‬\n‫ســئل عــن عــدم إيجــاد العمــل املناســب أفــاد أنــه لــم يبحــث عنــه مكتفيـ ًا‬\n‫مبــا يجلــب لــه أبنــاؤه مــن التســول وأســفر التحقيــق عــن اتهامــه بتــرك‬\n\n                                                                                             ‫‪334‬‬\n\f      ‫أفــراد أســرته بتكــرار التســول والتهــاون بإنهــاء إجراءاتهــم النظاميــة‬\n      ‫لالســتفادة مــن اجلمعيــات اخليريــة وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n      ‫‪ -1‬أقوالــه املنــوه عنهــا املدونــة ص(‪ )0‬مــن دفتــر التحقيــق املرفــق‪-2.‬‬\n      ‫محضــر القبــض املرفــق لفــة (‪ )8‬وببحــث ســوابقه عثــر لــه علــى ثــاث‬\n      ‫ســوابق مســجلة عليــه ترويــج قــات ودخــول وخــروج بطريقــة غيــر‬\n      ‫مشــروعة وتهريــب أفــراد وقــد تضمــن تعميــم صاحــب الســمو امللكــي‬\n      ‫أميــر منطقــة الريــاض رقــم ‪ 5801‬وتاريــخ ‪1429/3/18‬ه ـ القبــض علــى‬\n      ‫ولــي أمــر املتســول ســوءا كان امــرأة أو طفــا والتحقيــق معــه وإحالتــه‬\n      ‫للمحكمــة إن ثبــت تورطــه وحيــث إن مــا أقــدم عليــه املذكــور فعــل‬\n      ‫معاقــب عليــه أطلــب احلكــم عليــه بعقوبــة تعزيريــة ملــا نســب إليــه ‪ ،‬هــذه‬\n      ‫دعــواي وبعــرض ذلــك علــى املدعــى عليــه قــال ‪ :‬مــا ذكــره املدعــي العــام‬\n      ‫يف دعــواه كلــه صحيــح وقــد كان الدافــع لــي للتســول قلــة ذات اليــد‬\n      ‫وكثــرة الذريــة حيــث إننــي امتهــن أنــا وأفــراد أســرتي التســول لــم يكــن‬\n      ‫لــدي عمــل كمــا أن لــدي زوجتــن وعــدد أبنائــي ثمانيــة عشــر فــردا وقــد‬\n      ‫حصلــت علــى عمــل اآلن وأربعــة مــن أبنائــي اآلن يعملــون وأنــا متعهــد‬\n      ‫بتركــي للتســول ومبنعــي ألبنائــي أن ميارســوه فبنــاء علــى مــا تقــدم‬\n      ‫مــن الدعــوى واإلجابــة وحيــث ظهــر أن داعــي املدعــى عليــه للتســول‬\n      ‫هــو العــوز وحيــث حتصــل علــى عمــل يســد خلتــه وحيــث أظهــر ندمــه‬\n      ‫علــى ممارســته التســول لذلــك كلــه فقــد حكمــت بأخــذ التعهــد علــى‬\n      ‫املدعــى عليــه بعــدم العــودة ملــا بــدر منــه وأن يســتمر يف البحــث عــن املــال‬\n      ‫بطــرق شــريفة وبعــرض احلكــم عليــه قنــع بــه أمــا املدعــي العــام فلــم‬\n      ‫يقنــع وطلــب اســتئناف احلكــم بــدون الئحــة وأمــرت بإخــراج قــرار بذلــك‬\n      ‫وتســجيله ثــم بعثــه حملكمــة االســتئناف ونطــق باحلكــم الســاعة ‪01:30‬‬\n\n\n‫‪335‬‬\n\f‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                               ‫وســلم ‪ .‬حــرر يف ‪1434/4/1‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n‫الثالثــة لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض برقــم‬\n‫‪ 34790104‬وتاريــخ ‪1434/5/6‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ‪........... /‬املســجل برقــم ‪34176550‬‬\n‫وتاريــخ ‪1434/4/1‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد ‪ ...........‬يف‬\n‫قضيــة تســول علــى النحــو املوضــح بالقــرار املتضمــن حكــم فضيلتــه‬\n‫مبــا هــو مــدون و مفصــل بــه و بدراســة القــرار وصــورة ضبطــه وأوراق‬\n‫املعاملــة لــم يظهــر لألكثريــة مــا يوجــب املالحظــة علــى احلكــم مــع‬\n‫تنبيــه فضيلتــه الــى اثبــات االدانــة مــن عدمهــا قبــل احلكــم وفقـ ًا للمــادة‬\n‫(‪ )174‬مــن نظــام االجــراءات اجلزائيــة‪ .‬واهلل املوفــق وصلــى اهلل علــى‬\n                                    ‫نبينــا محمــد وعلــى الــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                       ‫‪336‬‬\n\f337\n\f338\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"ca29cb00-ff93-515e-9771-74b0d5d4a25f","source_page_start":333,"source_page_end":338,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b8ad187975fbbb50045e2e9b55887a516438966206ab0db540d9c3873653620f","normalized_text_hash":"4910a7363044f286560c38af53e4173fcaef307c1a9ff7a6fb8257d690e75c91","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v24-p333-34176550"},{"id":"92ca0663-9b24-56dd-a435-5b0b65823303","document_type":"judgment","category":"judicial","subcategory":"general","title":"غسيل أموال -حيازة مبلغ من املال نتيجة لبيع أمر محرم شرع ا ونظام ا -ثبوت -تعزير بالسجن -مصادرة .","document_number":"34191807","case_number":"33369022","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بجازان","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/20","year":"1434","subject":"غسيل أموال -حيازة مبلغ من املال نتيجة لبيع أمر محرم شرع ا ونظام ا -ثبوت -تعزير بالسجن -مصادرة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34191807 :‬تاريخه‪1434/4/20 :‬هـ‬\n                   ‫رقم الدعوى‪33369022 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34216303‬تاريخه‪1434/5/19 :‬هـ‬\n\n\n‫غســيل أمــوال ‪ -‬حيــازة مبلــغ مــن املــال نتيجــة لبيــع أمــر محــرم شــرع ًا‬\n                           ‫ونظام ـ ًا ‪ -‬ثبــوت ‪ -‬تعزيــر بالســجن ‪ -‬مصــادرة ‪.‬‬\n\n\n\n\n                  ‫املادة الثانية والسادسة عشرة من نظام غسيل األموال‪.‬‬\n\n\n\n\n‫اتهــام املدعــي العــام للمدعــى عليهمــا بقيامهمــا بجرميــة غســل أمــوال‬\n‫الرتكابهمــا اجلرائــم املنصــوص عليهــا يف املــادة الثانيــة (فقــرة ب)‬\n‫وذلــك باكتســاب أمــوال و حفظهــا و تلقيهــا ‪ ،‬مــع علمهمــا بأنهــا ناجتــة‬\n‫مــن نشــاط إجرامــي و مصــدر غيــر مشــروع وحيــث إن مــا أقــدم عليــه‬\n‫مجرمـ ًا ملــا ورد بنــص املــادة الثانيــة مــن نظــام‬\n                                                    ‫املدعــى عليهمــا يعــد فعــا ّ‬\n‫مكافحــة غســل األمــوال الصــادر باملرســوم امللكــي رقــم م‪ 39/‬وتاريــخ‬\n‫‪1424/6/25‬هــ‪ ،‬لــذا أطلــب تطبيــق املــادة ‪ 16‬مــن نظــام غســيل األمــوال‬\n‫بحقهمــا‪ ،‬حيــث مت القبــض علــى املدعــى عليهمــا مــن قبــل مكافحــة‬\n‫املخــدرات بصامطــة يف يــوم الســبت املوافــق ‪1433/5/8‬هــ‪ ،‬الســاعة‬\n‫الثانيــة عشــر ظهــر ًا ؛ حيــث كان يقــود املدعــى عليــه األول ‪ ...‬ســيارته‬\n‫مــن نــوع ‪ ....‬موديــل ‪ ...‬وحتمــل اللوحــة رقــم (‪ )...‬وكان راكب ـ ًا معــه‬\n‫املدعــى عليــه الثانــي ‪ ...‬وباالشــتباه بهمــا وبتفتيشــهما عثــر مــع املدعــى‬\n\n                                                                                      ‫‪344‬‬\n\f      ‫عليــه ‪ ...‬علــى مبلــغ قــدرة (‪ )17700‬ســبعة عشــر ألــف وســبعمائة ريــال‬\n      ‫ومــع (‪ )...‬علــى مبلــغ (‪ )10000‬عشــرة االف ريــال وأقــرا جميع ـ ًا عنــد‬\n      ‫الفرقــة القابضــة أنهــا ناجتــة عــن ترويجهــم للقــات علم ـ ًا بــأن اجلــواالت‬\n      ‫واملبالــغ املضبوطــة محجــوزة حلــن انتهــاء القضيــة‪ ،‬أقــر املدعــى عليــه‬\n      ‫األول مبــا جــاء يف الدعــوى وأنكــر الثانــي مــا جــاء فيهــا‪ ،‬أدلــة املدعــي‬\n                                                                                    ‫العــام ‪:‬‬\n      ‫‪ -1‬إقــرار املدعــى عليهمــا املتضمــن اعترافهمــا مبــا جــاء يف الدعــوى‬\n              ‫وبعرضــه علــى الثانــي أنكــره وأنــه صــدر منــه نتيجــة الضــرب‪.‬‬\n                                                     ‫‪ -2‬شهادة الشهود املعدلة شرع ًا ‪.‬‬\n             ‫ثبوت إدانة املدعى عليهما بجرمية غسل األموال واحلكم مبايلي ‪:‬‬\n         ‫‪ -1‬سجن كل واحد من املدعى عليهما مدة سنتني من تاريخ إيقافه‪.‬‬\n                                        ‫‪ -2‬مصادرة األموال املذكورة يف الدعوى ‪.‬‬\n      ‫‪ -‬قــرر املدعــي العــام عــدم القناعــة وطلــب االســتئناف بــدون الئحــة وقــرر‬\n                                                               ‫املدعــى عليهمــا القناعــة ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ............‬القاضــي يف احملكمــة‬\n      ‫العامــة بجــازان وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة بجــازان برقــم ‪ 33369022‬وتاريــخ ‪1433/05/29‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 331013804‬وتاريــخ ‪1433/05/29‬ه ـ‬\n      ‫ففــي يــوم الثالثــاء املوافــق ‪1433/06/17‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫‪ 09 : 00‬وفيهــا حضــر املدعــي العــام ‪ ..........‬املكلــف باالدعــاء العــام‬\n      ‫مــن ســعادة رئيــس هيئــة التحقيــق واالدعــاء العــام بجــازان مبوجــب‬\n\n‫‪345‬‬\n\f‫التعميــد رقــم(‪ )4018‬وتاريــخ ‪1433/2/2‬ه ـ وحضــر حلضــور املدعــى‬\n‫عليهمــا‪ ........-1‬ســعودي اجلنســية بالســجل املدنــي رقــم(‪.........-2)........‬‬\n‫مينــي اجلنســية مبوجــب البطاقــة البديلــة رقــم(‪ ).....‬وتاريــخ ‪1433/5/8‬ه ـ‬\n‫وادعــى املدعــي العــام بقولــه بصفتــي مدعيـ ًا عامـ ًا بدائــرة اإلدعــاء العــام‬\n‫لفــرع الهيئــة مبنطقــة جــازان أدعــي علــى املذكوريــن أعــاه بأنــه مت‬\n‫القبــض علــى املدعــى عليهــم املذكوريــن مــن قبــل مكافحــة املخــدرات‬\n‫بصامطــة يف يــوم الســبت املوافــق ‪1433/5/8‬ه ـ ‪ ،‬الســاعة الثانيــة عشــر‬\n‫ظهــر ًا ؛ حيــث كان يقــود املدعــى عليــه األول ‪....‬ســيارته مــن نــوع ‪...‬‬\n‫موديــل ‪ ...‬وحتمــل اللوحــة رقــم (‪ )....‬وكان راكب ـ ًا معــه املدعــى عليــه‬\n‫الثانــي ‪....‬وباالشــتباه بهمــا وبتفتيشــهما عثــر مــع املدعــى عليــه ‪ ....‬علــى‬\n‫مبلــغ قــدرة (‪ )17700‬ســبعة عشــر ألــف وســبعمائة ريــال ومــع (‪ ).....‬علــى‬\n‫مبلــغ (‪ )10000‬عشــرة االف ريــال وأقــرا جميع ـ ًا عنــد الفرقــة القابضــة‬\n‫أنهــا ناجتــة عــن ترويجهــم للقــات علمـ ًا بــأن اجلــواالت واملبالــغ املضبوطــة‬\n‫محجــوزة حلــن انتهــاء القضيــة ‪ .‬وبالتحقيــق مــع املدعــى عليــه األول‬\n‫ـداء أن املبلــغ يخــص صاحــب البقالــة ‪ ،......./‬وأنــه تعــرف علــى‬     ‫افــاد ابتـ ً‬\n‫املدعــى عليــه الثانــي قبــل حوالــي ســنة وأنــه جــاره ويســكن يف قريتــه ‪،‬‬\n‫وأن ســبب تقســيم املبلــغ أن كل واحــد منهمــا يعمــل يف وقــت حيــث أن‬\n‫املدعــى عليــه الثانــي يعمــل مــن الســاعة السادســة صباح ـ ًا إلــى املغــرب‬\n‫ا وكل‬     ‫ثــم هــو يســتلم البقالــة مــن املغــرب الــى الســاعة الثانيــة عشــر ليـ ً‬\n‫واحــد منهمــا يحمــل حصيلــة عملــه ‪ ،‬وأن منزلــه يبعــد عــن البقالــة حوالي‬\n‫ثالثــن متــر ًا فقــط ‪ ،‬ثــم بعــد ذلــك عــدل عــن أقوالــه بعــد املواجهــة بينهمــا‬\n‫يف تناقــض أقوالهمــا وأقــر بــأن املبلــغ عائــد مــن بيعهمــا للقــات حيــث أنــه‬\n‫يشــتري مــن (‪ 40‬حزمــة إلــى ‪ 50‬حزمــة ) ويبعهــا علــى مــن يريــد الشــراء‬\n\n\n                                                                                           ‫‪346‬‬\n\f      ‫وأن املبلــغ املضبــوط معــه حصيلــة عمــل أربعــة أيــام مــن بيــع القــات وأن‬\n      ‫املتهــم الثانــي كذلــك يعمــل يف بيــع القــات واالمــوال التــي معــه ناجتة عن‬\n      ‫ذلــك وباملواجهــة بينهمــا أصــر كل واحــد منهمــا علــى أقوالــه وبالتحقيــق‬\n      ‫مــع املدعــى عليــه الثانــي أنكــر ذلــك وأن اقوالــه لــدى الفرقــة القابضــة‬\n      ‫كان مجبــر ًا عليهــا وأفــاد أن املبالــغ املضبوطــة تعــود لصاحــب البقالــة‬\n      ‫التــي يعمــل بهــا هــو واملدعــى عليــه األول وأن الفلــوس كانــت معهمــا‬\n      ‫لشــراء بضائــع للبقالــة وبســؤاله عــن ســبب تقســيم املبلــغ بينهــا أفــاد أن‬\n      ‫املبلــغ كبيــر علــى جيــب الثــوب فاقتســما املبلــغ بينهمــا ‪ ،‬وأنــه تعــرف‬\n      ‫علــى املدعــى عليــه األول قبــل حوالــي ســنة وأن اســم صاحــب البقالــة‬\n      ‫التــي يعمــان بهــا ســوي ًا هــو ‪..... /‬؛ وأنــه ليــس قريبـ ًا لــه وإمنــا تعــرف عليــه‬\n      ‫بعــد نزوحــه إلــى قريــة ‪ ، ........‬كمــا أفــاد أن منــزل املدعــى عليــه األول‬\n      ‫يبعــد عــن البقالــة حوالــي اثنــن كيلــو الــى ثالثــة كيلــو تقريباً‪،‬وأفــاد‬\n      ‫أنــه ال يســكن يف نفــس قريــة املدعــى عليــه األول وكل واحــد منهمــا يف‬\n      ‫قريــة وقــد أســفر التحقيــق مــع املدعــى عليهمــا بتوجيــه االتهــام اليهمــا‬\n      ‫بجرميــة غســل أمــوال الرتكابهمــا اجلرائــم املنصــوص عليهــا يف املــادة‬\n      ‫الثانيــة (فقــرة ب) وذلــك باكتســاب أمــوال وحفظهــا وتلقيهــا ‪ ،‬مــع‬\n      ‫علمهمــا بأنهــا ناجتــة مــن نشــاط إجرامــي و مصــدر غيــر مشــروع وحيــث‬\n      ‫مجرم ـ ًا ملــا‬\n                  ‫إن مــا أقــدم عليــه املدعــى عليهمــا املذكــوران يعــد فعــا ّ‬\n      ‫ورد بنــص املــادة الثانيــة مــن نظــام مكافحــة غســل األمــوال الصــادر‬\n      ‫باملرســوم امللكــي رقــم م‪ 39/‬وتاريــخ ‪1424/6/25‬ه ـ ‪ ،‬لــذا اطلــب‬\n      ‫تطبيــق النظــام بحقهمــا وفقـ ًا للمــادة (‪ )16‬مــن النظــام املشــار إليــه هــذه‬\n      ‫دعــواي وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه األول فأجــاب‬\n      ‫بقولــه ماذكــره املدعــي العــام صحيــح ومبلــغ العشــرة آالف ريــال التــي‬\n\n\n‫‪347‬‬\n\f‫قبــض علــي وهــي بحوزتــي ناجتــة مــن بيــع القــات وكنــت ابيعــه يف نفــس‬\n‫احملــل هكــذا أجــاب وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه‬\n‫الثانــي فأجــاب بقولــه مــا ذكــره املدعــي العــام غيــر صحيــح والصحيــح‬\n‫أنــه قبــض علــي يف يــوم الســبت‪1433/5/8‬هـ وكان بحوزتي مبلغ ســبعة‬\n‫عشــر ألــف وســبعمائة ريــال وهــي تعــود لصاحــب البقالــة التــي أعمــل‬\n‫فيهــا واســمه ‪ ............‬وكنــت ذاهب ـ ًا إليصالهــا إليــه وعنــدي الفواتيــر‬\n‫التــي تثبــت ذلــك هكــذا أجــاب وبعــرض جــواب املدعــى عليــه الثانــي‬\n‫علــى املدعــى العــام قــال الصحيــح مــا جــاء يف دعــواي وبســؤال املدعــي‬\n‫العــام عــن بينتــه علــى مــا انكــره املدعــى عليــه الثانــي أجــاب بــأن بينتــي‬\n‫مــا يف أوراق املعاملــة وهــي ‪ -1‬محضــر القبــض املــدون مبلــف اجــراءات‬\n‫االســتدالل علــى الصفحــة (‪ )11‬املرفــق باللفــة (‪ -2 )1‬اقــرار املتهــم األول‬\n‫املــدون بدفتــر التحقيــق علــى الصفحــة (‪ )10-9‬املرفــق باللفــة (‪-3)7‬‬\n‫تناقــض اقوالهمــا ‪ -4‬محضــر املواجهــة املــدون بدفتــر التحقيــق علــى‬\n‫الصفحــة (‪ )8‬املرفــق باللفــة (‪ )7‬وباالطــاع علــى أوراق املعاملــة وجــد‬\n‫علــى لفــة رقــم (‪ )1‬صحيفــة رقــم (‪ )12‬مــن محضــر القبــض ( اقــرار يف‬\n‫تاريــخ ‪1433/5/8‬ه ـ ونصــه‪ :‬نقــر نحــن املقبــوض علينــا املوقعــن ادنــاه‬\n‫انــه يف متــام الســاعة الثانيــة عشــر ظهــر هــذا اليــوم الســبت املوافــق أعــاه‬\n‫قبــض علينــا وعثــر بحــوزة كل منــا علــى املبلــغ املوضــح أمــام اســمه‬\n‫بالصفحــة رقــم (‪ )7‬وأن هــذا املبلــغ عائــد مــن بيــع وترويــج القــات وســوف‬\n‫نقــوم بتحويلــه لشــخص يف اليمــن يدعــى ‪ ....‬وعليــه نوقــع املقــر مبــا فيــه‬\n‫‪.....‬بصمــة ابهــام املقــر مبــا فيــه ‪.....‬بصمــة ابهــام) وبعرضــه علــى املدعــى‬\n‫عليــه الثانــي قــال إننــي أقريــت بهــذا الــكالم نتيجــة الضــرب ومــا جــاء‬\n‫فيــه غيــر صحيــح وبســؤال املدعــي العــام هــل لديــك زيــادة بينــه علــى‬\n\n\n                                                                                        ‫‪348‬‬\n\f      ‫مــا أنكــر عليــه املدعــى عليــه الثانــي فقــال نعــم واطلــب رفــع اجللســة‬\n      ‫إلحضارهــا فأجبتــه لطلبــه ويف يــوم األحــد املوافــق‪ 1433/08/11‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة العشــرة وفيهــا حضــر املدعــى العــام وحضــر‬\n      ‫املدعــى عليهمــا وجــرى ســؤال املدعــي العــام عمــا طلــب املهلــة ألجلــة‬\n      ‫فقــال أطلــب رفــع اجللســة مــرة أخــرى إلحضارهــا عنــد ذلــك قــررت رفــع‬\n      ‫اجللســة لذلــك وجــرى أفهــام املدعــي العــام أن هــذا هــي املهلــة األخيــرة‬\n      ‫ففهــم ذلــك ويف يــوم الثالثــاء املوافــق‪ 1434/02/26‬ه ـ افتتحــت اجللســة‬\n      ‫الســاعة الثامنــة وفيهــا حضــر املدعــي العــام وحضــر حلضــور املدعــى‬\n      ‫عليهمــا ثــم جــرى ســؤال املدعــي العــام عمــا طلــب منــه يف اجللســة‬\n      ‫ا لقــد أحضــرت معــي شــاهدين وأطلــب ســماع مــا‬      ‫الســابقة فأجــاب قائـ ً‬\n      ‫لديهمــا مــن شــهادة ثــم حضــر‪...... -1‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم ‪ ......‬املولــود يف ‪1408/8/20‬ه ـ الــذي يعمــل يف مكافحــة‬\n      ‫املخــدرات بصامطــة ويســكن ‪ ..............‬وبســؤاله عمــا لديــه مــن شــهادة‬\n      ‫قــال (أشــهد هلل بأننــي قبضــت علــى املدعــي عليهمــا يف مــكان يكثــر‬\n      ‫فيــه القــات وجــرى تفتشــيهما ولــم جنــد معهــم قــات ولكــن وجــدت مــع‬\n      ‫‪ .....‬مبلــغ مالــي وقــدره (‪ )17،700‬الــف ريــال ومــع ‪ ........‬مبلــغ مالــي‬\n      ‫وقــدره (‪ )000،10‬الــف ريــال وقــد ذكــرا لــي أنهــا فلــوس قــات) هكــذا‬\n      ‫شــهد ‪ ...... -2‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....‬املولــود‬\n      ‫يف ‪1409/8/23‬ه ـ ويعمــل يف مكافحــة املخــدرات بصامطــة ويســكن‬\n      ‫يف محافظــة العارضــة وبســؤاله عمــا لديــه مــن شــهادة قــال (أشــهد هلل‬\n      ‫بأننــي قبضــت علــى املدعــي عليهمــا يف مــكان يكثــر فيــه القات وجرى‬\n      ‫تفتشــيهما ولــم يكــن معهــم قــات ولكــن وجدنــا مــع ‪ ...‬مبلــغ مالــي‬\n      ‫وقــدره (‪ )17.700‬الــف ريــال ومــع ‪ .....‬مبلــغ مالــي وقــدره (‪)10.000‬‬\n\n\n‫‪349‬‬\n\f‫ألــف ريــال وقــد ذكــرا لــي أن هــذه فلــوس قــات) هكــذا شــهد وبعــرض‬\n‫الشــاهدين وشــهادتهما علــى املدعــى عليــه الثانــي قــال ان الشــاهد‬\n‫‪...‬كان موجــود ًا وقــت القبــض أمــا الشــاهد ‪....‬فلــم يكــن موجــود ًا وقــت‬\n‫القبــض وقــد قلــت لهــم أن هــذه الفلــوس مــن القــات بعــد ماضربونــي وال‬\n‫أعــرف الشــاهدين وال أقــول فيهــم شــيئ ًا فجــرى ســؤاله هــل لديــه بينــة‬\n‫علــى ذلــك فقــال ال وجــرى ســؤال الشــاهد ‪.....‬هــل كان موجــود وقــت‬\n‫القبــض فقــال نعــم ولكنــي كنــت يف ســيارة اخرى هكــذا أجاب وعند‬\n‫ذلــك قــررت رفــع اجللســة لطلــب مزكــن مــن املدعــي العــام لشــهوده ويف‬\n‫يــوم األحــد املوافــق‪ 1434/03/01‬ه ـ افتتحــت اجللســة الســاعة العاشــرة‬\n‫وفيهــا حضــر املدعــي العــام وحضــر حلضــوره املدعــى عليهمــا ثــم جــرى‬\n‫ســؤال املدعــي العــام عمــا طلــب منــه يف اجللســة الســابقة فأجــاب بقولــه‬\n‫لقــد أحضــرت معــي مزكيــن للشــاهدين اللذيــن أحضرتهــم يف اجللســة‬\n‫الســابقة ثــم حضــر ‪ ......-1‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم(‪ ......-2 )........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪).....‬‬\n‫وبســؤالهما عــن حــال الشــاهدين شــهدا بعدالــة وثقــة الشــاهدين أعــاه‬\n‫ونظــر ًا إلنتهــاء وقــت اجللســة قــررت رفعهــا للتأمــل ويف هــذا اليــوم االحــد‬\n‫املوافــق ‪1434/3/8‬ه ـ افتتحــت اجللســة الســاعة الثانيــة عشــر وفيهــا‬\n‫حضــر املدعــي العــام وحضــر حلضــوره املدعــى عليهمــا وجــرى منــي تأمــل‬\n‫مــا ســبق واالطــاع علــى أوراق املعاملــة ووجــدت بهــا كرتــي ســوابق‬\n‫املدعــى عليهمــا املرفقــان باملعاملــة لفــه رقــم(‪ )13‬و(‪ )14‬واملتضمنــان‬\n‫عــدم وجــود ســوابق عليهمــا فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n‫وحيــث صــادق املدعــى عليــه األول علــى ماجــاء يف دعــوى املدعــي‬\n‫العــام وانكرهــا املدعــى عليــه الثانــي ‪ ....‬وحيــث شــهدت بينــة املدعــي‬\n\n\n                                                                                       ‫‪350‬‬\n\f      ‫العــام علــى مــا أنكــره املدعــى عليــه الثانــي وبعــد االطــاع علــى املــواد‬\n      ‫(‪)16،2‬مــن نظــام مكافحــة غســيل األمــوال فقــد ثبــت لــدي ادانــة‬\n      ‫املدعــى عليهمــا بجرميــة غســل األمــوال وحكمــت مبايلي‪-1‬ســجن كل‬\n      ‫واحــد مــن املدعــى عليهمــا مــدة ســنتني مــن تاريــخ إيقافه‪-2‬مصــادرة‬\n      ‫األمــوال املذكــورة يف الدعــوى وبعــرض احلكــم علــى املدعــى عليهمــا‬\n      ‫وعلــى املدعــي العــام قنــع بــه املدعــى عليهمــا وقــرر املدعــي العــام عــدم‬\n      ‫القناعــة وطلــب رفعــه حملكمــة االســتئناف بــدون الئحــة اعتراضيــة‬\n      ‫فأجبتــه لطلبــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/03/08‬ه ـ‬\n      ‫احلمــد اهلل وحــده وبعــد ففــي يــوم الســبت املوافــق ‪1434/6/24‬ه ـ‬\n      ‫افتتحــت اجللســة يف متــام الســاعة الثانيــة عشــر والنصــف وقــد وردنــا‬\n      ‫خطــاب فضيلــة رئيــس محكمــة االســتئناف مبنطقــة عســير رقــم‬\n      ‫(‪ )341132270‬وتاريــخ ‪1434/6/5‬ه ـ واملرفــق بــه قــرار الدائرة اجلزائية‬\n      ‫الثانيــة لتدقيــق القضايــا مبحكمــة االســتئناف مبنطقــة عســير برقــم‬\n      ‫(‪ )34216303‬وتاريــخ ‪1434/5/19‬ه ـ ونــص احلاجــة منــه (وبدراســة‬\n      ‫القــرار الشــرعي وصــورة ضبطــه وأوراق املعاملــة تقــررت املوافقــة علــى‬\n      ‫احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n      ‫وســلم قاضــي اســتئناف ‪.....‬ختــم وتوقيــع قاضــي اســتئناف ‪.....‬ختــم‬\n      ‫وتوقيــع رئيــس الدائــرة ‪ .....‬ختــم وتوقيــع) وحتــى ال يخفــى جــرى إحلاقــه‬\n      ‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف‬\n                                                                      ‫‪1434/6/24‬ه ـ‬\n\n\n\n\n‫‪351‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"ca29cb00-ff93-515e-9771-74b0d5d4a25f","source_page_start":344,"source_page_end":351,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ba63d0e58bcffbef68a11a0125adfe15a53e91a01bfabf6f307626e05b51ba62","normalized_text_hash":"945888cbc494bc5e8a6880b58b39c5b9acca19701953306f2a4e6e8ab960f4c0","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v24-p344-34191807"}]$archive_payload$::jsonb AS data)
